window.QS=[{"id": 1, "t": 0, "q": "What is a characteristic of a fault tolerant network?", "o": ["Protects data from unauthorized access", "Grows quickly without hurting existing users", "Manages congestion and guarantees delivery", "Recovers quickly from failure thanks to redundancy"], "a": 3, "e": "Redundant paths limit the impact of a failure. Growth = scalability; congestion = QoS."}, {"id": 2, "t": 0, "q": "With QoS, what is the priority order (highest to lowest): web page, financial transactions, live audio conference?", "o": ["financial, audio, web", "audio, financial, web", "audio, web, financial", "financial, web, audio"], "a": 1, "e": "Real-time voice first, then transactions, then web browsing."}, {"id": 3, "t": 0, "q": "Which name is assigned to the transport layer PDU?", "o": ["bits", "frame", "packet", "segment"], "a": 3, "e": "Segment = L4, packet = L3, frame = L2, bits = L1."}, {"id": 4, "t": 0, "q": "Which protocol controls segment size and the rate of exchange between a web client and server?", "o": ["TCP", "IP", "HTTP", "Ethernet"], "a": 0, "e": "TCP (Layer 4) splits data into segments and controls the rate with windowing."}, {"id": 5, "t": 0, "q": "Which trend lets users reach corporate resources from personal laptops and phones?", "o": ["BYOD", "Video conferencing", "Cloud computing", "Online collaboration"], "a": 0, "e": "BYOD = Bring Your Own Device."}, {"id": 6, "t": 0, "q": "Which TCP/IP layer is responsible for routing messages through an internetwork?", "o": ["Transport", "Internet", "Network access", "Session"], "a": 1, "e": "The Internet layer (IP) routes. The session layer exists only in OSI."}, {"id": 7, "t": 1, "q": "Which connection provides a secure, encrypted CLI session to a Cisco device?", "o": ["Console", "AUX", "Telnet", "SSH"], "a": 3, "e": "SSH encrypts the session; Telnet sends everything in clear text."}, {"id": 8, "t": 1, "q": "The command ip address 192.168.2.1 255.255.255.0 is rejected at the SanJose(config)# prompt. Why?", "o": ["Wrong mode of operation", "Wrong syntax", "Wrong subnet mask", "Interface is shut down"], "a": 0, "e": "IP addresses are set in interface config mode (config-if)#, not global config."}, {"id": 9, "t": 1, "q": "Which key combination interrupts an IOS process such as ping or traceroute?", "o": ["Ctrl-Z", "Ctrl-C", "Ctrl-Shift-6", "Ctrl-R"], "a": 2, "e": "Ctrl-Shift-6 interrupts. Ctrl-Z exits config mode, Ctrl-C aborts the current command."}, {"id": 10, "t": 1, "q": "On which switch interface is an IP address configured for remote management?", "o": ["FastEthernet0/1", "VLAN 1 (SVI)", "vty 0", "console 0"], "a": 1, "e": "The SVI (interface VLAN 1) is a virtual interface that can hold the management IP."}, {"id": 11, "t": 1, "q": "Where is the configuration saved by copy running-config startup-config?", "o": ["Flash", "ROM", "NVRAM", "RAM"], "a": 2, "e": "startup-config lives in NVRAM (non-volatile) and loads at boot."}, {"id": 12, "t": 1, "q": "Where are Cisco IOS debug messages sent by default?", "o": ["Syslog server", "Console line", "Memory buffer", "vty lines"], "a": 1, "e": "Console by default; use terminal monitor to see them over vty."}, {"id": 13, "t": 2, "q": "Which is a characteristic of fiber-optic cable?", "o": ["Not affected by EMI/RFI", "Uses twisting for cancellation", "Cheaper than UTP", "Wrapped in metallic foil"], "a": 0, "e": "Fiber carries light, so it is immune to EMI/RFI (but costs more than UTP)."}, {"id": 14, "t": 2, "q": "An Ethernet host receives a frame whose destination MAC is not its own. What does it do?", "o": ["Discards the frame", "Forwards it to the next host", "Strips the frame to read the IP", "Removes it from the media"], "a": 0, "e": "Every NIC compares the destination MAC with its own; no match = discard."}, {"id": 15, "t": 2, "q": "A switch receives a frame with an unknown destination MAC. What does it do?", "o": ["Sends an ARP request", "Floods it out all ports except the incoming one", "Drops it", "Notifies the sender"], "a": 1, "e": "Unknown unicast and broadcast frames are flooded (except the ingress port)."}, {"id": 16, "t": 2, "q": "Which switching method has the lowest latency?", "o": ["Store-and-forward", "Fragment-free", "Fast-forward", "CRC switching"], "a": 2, "e": "Fast-forward forwards right after reading the destination MAC."}, {"id": 17, "t": 2, "q": "What destination address is used in an ARP request frame?", "o": ["0.0.0.0", "255.255.255.255", "FFFF.FFFF.FFFF", "127.0.0.1"], "a": 2, "e": "ARP request is a Layer 2 broadcast: FFFF.FFFF.FFFF."}, {"id": 18, "t": 2, "q": "Which method manages contention-based access on a wireless network?", "o": ["CSMA/CD", "Token passing", "CSMA/CA", "Priority ordering"], "a": 2, "e": "Wi-Fi uses CSMA/CA (avoidance); wired Ethernet used CSMA/CD (detection)."}, {"id": 19, "t": 3, "q": "How many valid host addresses are on a /26 subnet?", "o": ["64", "62", "30", "126"], "a": 1, "e": "6 host bits: 2^6 − 2 = 62."}, {"id": 20, "t": 3, "q": "Which mask supports 126 hosts?", "o": ["255.255.255.0", "255.255.255.128", "255.255.255.224", "255.255.255.240"], "a": 1, "e": "/25 has 7 host bits: 2^7 − 2 = 126."}, {"id": 21, "t": 3, "q": "How many hosts are addressable with mask 255.255.255.248?", "o": ["2", "6", "8", "14"], "a": 1, "e": "/29: 3 host bits, 8 − 2 = 6 usable."}, {"id": 22, "t": 3, "q": "Which address is private?", "o": ["172.32.5.2", "192.167.10.10", "172.20.4.4", "224.6.6.6"], "a": 2, "e": "Private: 10/8, 172.16–172.31, 192.168/16. 224.x is multicast."}, {"id": 23, "t": 3, "q": "Most compressed form of 2001:0000:0000:abcd:0000:0000:0000:0001?", "o": ["2001:0:abcd::1", "2001:0:0:abcd::1", "2001::abcd::1", "2001:0000:abcd::1"], "a": 1, "e": "Drop leading zeros; use :: once for the longest zero run."}, {"id": 24, "t": 3, "q": "Convert 11001011.00000000.01110001.11010011 to dotted decimal.", "o": ["192.0.2.199", "198.51.100.201", "203.0.113.211", "209.165.201.223"], "a": 2, "e": "11001011=203, 01110001=113, 11010011=211."}, {"id": 25, "t": 4, "q": "What do both TCP and UDP use to identify applications?", "o": ["Port numbers", "3-way handshake", "Connection orientation", "Sliding window"], "a": 0, "e": "Both use source/destination ports. Handshake and windows are TCP only."}, {"id": 26, "t": 4, "q": "Which protocol uses UDP for client-to-server and TCP for server-to-server?", "o": ["FTP", "HTTP", "DNS", "SMTP"], "a": 2, "e": "DNS: UDP for client queries, TCP for zone transfers between servers."}, {"id": 27, "t": 4, "q": "A DHCPv4 client gets several DHCPOFFERs. What does it do?", "o": ["Sends one DHCPREQUEST naming the chosen server", "Sends DHCPNAK", "Discards offers and re-sends DISCOVER", "Accepts all and sends DHCPACK"], "a": 0, "e": "The client picks one offer and broadcasts a single DHCPREQUEST."}, {"id": 28, "t": 4, "q": "Which example is a Trojan horse?", "o": ["Malware disguised as a video game", "Worm spreading via a vulnerability", "Code attaching itself to legit programs", "Malware needing manual spread"], "a": 0, "e": "A Trojan looks like a legitimate program. Virus attaches; worm self-spreads."}, {"id": 29, "t": 4, "q": "Which command helps mitigate brute-force password attacks on a router?", "o": ["exec-timeout 30", "service password-encryption", "login block-for 60 attempts 5 within 60", "banner motd"], "a": 2, "e": "login block-for blocks logins after too many failures."}, {"id": 30, "t": 4, "q": "Why does HTTP use TCP?", "o": ["Fastest download", "It is best-effort", "Errors are tolerable", "HTTP requires reliable delivery"], "a": 3, "e": "A web page must arrive complete, so TCP's reliability is needed."}, {"id": 31, "t": 0, "q": "What is the purpose of having a converged network?", "o": ["High-speed connectivity for all end devices", "Treat all data packets equally", "Fault tolerance and high availability", "Reduce the cost of deploying and maintaining the infrastructure"], "a": 3, "e": "Voice, video and data share one network, so one infrastructure to build and maintain means lower cost."}, {"id": 32, "t": 0, "q": "Which characteristic lets a network grow quickly without hurting existing users?", "o": ["Reliability", "Scalability", "Quality of service", "Accessibility"], "a": 1, "e": "Scalability = growing without hurting existing users and services."}, {"id": 33, "t": 0, "q": "Which term refers to a network giving suppliers, customers and collaborators secure access to corporate offices?", "o": ["Internet", "Intranet", "Extranet", "Extendednet"], "a": 2, "e": "Extranet = secure access for outside partners; intranet = internal only; extendednet does not exist."}, {"id": 34, "t": 1, "q": "Which command shows Layer 1 and Layer 2 details of a switch port (duplex, speed)?", "o": ["show mac-address-table", "show ip interface brief", "show interfaces", "show running-config"], "a": 2, "e": "show interfaces shows speed, duplex, media type and other L1/L2 details."}, {"id": 35, "t": 1, "q": "What does the Tab key do when entering an IOS command?", "o": ["Aborts the command", "Exits configuration mode", "Moves the cursor to the next line", "Completes the partially typed word"], "a": 3, "e": "Tab completes a partially typed command or keyword."}, {"id": 36, "t": 1, "q": "An admin enabled service password-encryption, then issues no service password-encryption. What happens?", "o": ["Encryption is removed from all passwords", "Only vty and console passwords are decrypted", "No encryption is reversed", "Only the enable password is decrypted"], "a": 2, "e": "Encryption already applied is not reversed by the no form; it only affects new passwords."}, {"id": 37, "t": 2, "q": "Which type of UTP cable connects a PC to a switch port?", "o": ["Console", "Rollover", "Crossover", "Straight-through"], "a": 3, "e": "Straight-through connects different devices (PC–switch); crossover connects like devices."}, {"id": 38, "t": 2, "q": "A device receives an Ethernet frame of 60 bytes. What does it do?", "o": ["Drops the frame", "Processes it as is", "Sends an error to the sender", "Pads it to 64 bytes and forwards it"], "a": 0, "e": "The minimum Ethernet frame is 64 bytes; shorter runt frames are discarded."}, {"id": 39, "t": 2, "q": "Which procedure reduces crosstalk in copper cables?", "o": ["Proper grounding", "Twisting opposing circuit wire pairs", "Wrapping the bundle in metallic shielding", "Avoiding sharp bends"], "a": 1, "e": "Twisting opposing wire pairs cancels crosstalk; the others fight EMI/RFI."}, {"id": 40, "t": 3, "q": "Which subnet mask is needed for 40 devices without wasting address space?", "o": ["255.255.255.0", "255.255.255.128", "255.255.255.192", "255.255.255.224"], "a": 2, "e": "40 hosts need 6 host bits (62 usable) → /26 = 255.255.255.192."}, {"id": 41, "t": 3, "q": "What is the minimum address required on IPv6-enabled interfaces?", "o": ["Link-local", "Unique local", "Site local", "Global unicast"], "a": 0, "e": "Every IPv6 interface needs at least a link-local address."}, {"id": 42, "t": 3, "q": "What type of IPv6 address is FE80::1?", "o": ["Loopback", "Link-local", "Multicast", "Global unicast"], "a": 1, "e": "FE80::/10 is the link-local range."}, {"id": 43, "t": 4, "q": "What does ping 127.0.0.1 test?", "o": ["The TCP/IP stack on the host", "Connectivity between two adjacent Cisco devices", "Connectivity between a PC and the default gateway", "Connectivity between two PCs on the same network"], "a": 0, "e": "127.0.0.1 is loopback: it tests only the host's own TCP/IP stack."}, {"id": 44, "t": 4, "q": "Which technology lets multiple devices share one public IPv4 address?", "o": ["ARP", "DNS", "NAT", "DHCP"], "a": 2, "e": "NAT lets many private hosts share a few public IPv4 addresses."}, {"id": 45, "t": 4, "q": "What does a client do when it has UDP datagrams to send?", "o": ["Sends a segment with the SYN flag", "Just sends the datagrams", "Asks the server if it is ready", "Performs a simplified three-way handshake"], "a": 1, "e": "UDP is connectionless: the client just sends the datagrams."}, {"id": 46, "t": 1, "q": "Three bank employees are using the corporate network. The first employee uses a web browser to view a company web page in order to read some announcements. The second employee accesses the corporate database to perform some financial transactions. The third employee participates in an important live audio conference with other corporate managers in branch offices. If QoS is implemented on this network, what will be the priorities from highest to lowest of the different data types?", "o": ["financial transactions, audio conference, web page", "audio conference, financial transactions, web page", "audio conference, web page, financial transactions", "financial transactions, web page, audio conference"], "a": 1, "e": " QoS mechanisms enable the establishment of queue management strategies that enforce priorities for different categories of application data. Thus, this queuing enables voice data to have priority over transaction data, which has priority over web data."}, {"id": 47, "t": 2, "q": "What is a benefit of using cloud computing in networking?", "o": ["End users have the freedom to use personal tools to access information and communicate across a business network.", "Network capabilities are extended without requiring investment in new infrastructure, personnel, or software.", "Technology is integrated into every-day appliances allowing them to interconnect with other devices, making them more ‘smart’ or automated.", "Home networking uses existing electrical wiring to connect devices to the network wherever there is an electrical outlet, saving the cost of installing data cables."], "a": 1, "e": " Cloud computing extends IT’s capabilities without requiring investment in new infrastructure, training new personnel, or licensing new software. These services are available on-demand and delivered economically to any device anywhere in the world without compromising security or function. BYOD is about end users having the freedom to use personal tools to access information and communicate across a business or campus network. Smart home technology is integrated into every-day appliances allowing them to interconnect with other devices, making them more ‘smart’ or automated. Powerline networking is a trend for home networking that uses existing electrical wiring to connect devices to the net"}, {"id": 48, "t": 4, "q": "What is the function of the shell in an OS?", "o": ["It interacts with the device hardware.", "It interfaces between the users and the kernel.", "It provides dedicated firewall services.", "It provides the intrusion protection services for the device."], "a": 1, "e": " Most operating systems contain a shell and a kernel. The kernel interacts with the hardware and the shell interfaces between the kernel and the users."}, {"id": 49, "t": 1, "q": "A network technician is attempting to configure an interface by entering the following command: SanJose(config)# ip address 192.168.2.1 255.255.255.0. The command is rejected by the device. What is the reason for this?", "o": ["The command is being entered from the wrong mode of operation.", "The command syntax is wrong.", "The subnet mask information is incorrect.", "The interface is shutdown and must be enabled before the switch will accept the IP address."], "a": 0, "e": " The wrong mode of operation is being used. The CLI prompt indicates that the mode of operation is global configuration. IP addresses must be configured from interface configuration mode, as indicated by the SanJose(config-if)# prompt."}, {"id": 50, "t": 1, "q": "An administrator uses the Ctrl-Shift-6 key combination on a switch after issuing the ping command. What is the purpose of using these keystrokes?", "o": ["to restart the ping process", "to interrupt the ping process", "to exit to a different configuration mode", "to allow the user to complete the command"], "a": 1, "e": " To interrupt an IOS process such as ping or traceroute, a user enters the Ctrl-Shift-6 key combination. Tab completes the remainder of parameters or arguments within a command. To exit from configuration mode to privileged mode use the Ctrl-Z keystroke. CTRL-R will redisplay the line just typed, thus making it easier for the user to press Enter and reissue the ping command."}, {"id": 51, "t": 1, "q": "Refer to the exhibit. A network administrator is configuring access control to switch SW1. If the administrator uses a console connection to connect to the switch, which password is needed to access user EXEC mode? <i>(exhibit not shown)</i>", "o": ["letmein", "secretin", "linevtyin", "lineconin"], "a": 3, "e": " Telnet accesses a network device through the virtual interface configured with the line VTY command. The password configured under this is required to access the user EXEC mode. The password configured under the line console 0 command is required to gain entry through the console port, and the enable and enable secret passwords are used to allow entry into the privileged EXEC mode."}, {"id": 52, "t": 2, "q": "On which switch interface would an administrator configure an IP address so that the switch can be managed remotely?", "o": ["FastEthernet0/1", "VLAN 1", "vty 0", "console 0"], "a": 1, "e": " Interface VLAN 1 is a virtual interface on a switch, called SVI (switch virtual interface). Configuring an IP address on the default SVI, interface VLAN 1, will allow a switch to be accessed remotely. The VTY line must also be configured to allow remote access, but an IP address cannot be configured on this line."}, {"id": 53, "t": 4, "q": "What protocol is responsible for controlling the size of segments and the rate at which segments are exchanged between a web client and a web server?", "o": ["TCP", "IP", "HTTP", "Ethernet"], "a": 0, "e": " TCP is a Layer 4 protocol of the OSI model. TCP has several responsibilities in the network communication process. It divides large messages into smaller segments which are more efficient to send across the network. It also controls the size and rate of segments exchanged between clients and servers."}, {"id": 54, "t": 1, "q": "What is an advantage to using a protocol that is defined by an open standard?", "o": ["A company can monopolize the market.", "The protocol can only be run on equipment from a specific vendor.", "An open standard protocol is not controlled or regulated by standards organizations.", "It encourages competition and promotes choices."], "a": 3, "e": " A monopoly by one company is not a good idea from a user point of view. If a protocol can only be run on one brand, it makes it difficult to have mixed equipment in a network. A proprietary protocol is not free to use. An open standard protocol will in general be implemented by a wide range of vendors."}, {"id": 55, "t": 1, "q": "What are two benefits of using a layered network model? (Choose two.)", "o": ["It assists in protocol design.", "It speeds up packet delivery.", "It prevents designers from creating their own model.", "It prevents technology in one layer from affecting other layers.", "It ensures a device at one layer can function at the next higher layer."], "a": [0, 3], "e": " Some vendors have developed their own reference models and protocols. Today, if a device is to communicate on the Internet, the device must use the TCP/IP model. The benefits of using a layered model are as follows: assists in protocol design fosters competition between vendors prevents a technology that functions at one layer from affecting any other layer provides a common language for describing network functionality helps in visualizing the interaction between each layer and protocols between each layer"}, {"id": 56, "t": 4, "q": "Which two OSI model layers have the same functionality as two layers of the TCP/IP model? (Choose two.)", "o": ["data link", "network", "physical", "session", "transport"], "a": [1, 4], "e": " The OSI transport layer is functionally equivalent to the TCP/IP transport layer, and the OSI network layer is equivalent to the TCP/IP internet layer. The OSI data link and physical layers together are equivalent to the TCP/IP network access layer. The OSI session layer (with the presentation layer) is included within the TCP/IP application layer."}, {"id": 57, "t": 2, "q": "A network engineer is measuring the transfer of bits across the company backbone for a mission critical database application. The engineer notices that the network throughput appears lower than the bandwidth expected. Which three factors could influence the differences in throughput? (Choose three.)", "o": ["the amount of traffic that is currently crossing the network", "the sophistication of the encapsulation method applied to the data", "the type of traffic that is crossing the network", "the latency that is created by the number of network devices that the data is crossing", "the bandwidth of the WAN connection to the Internet", "the reliability of the gigabit Ethernet infrastructure of the backbone"], "a": [0, 2, 3], "e": " Throughput usually does not match the specified bandwidth of physical links due to multiple factors. These factors include, the amount of traffic, type of traffic, and latency created by the network devices the data has to cross."}, {"id": 58, "t": 2, "q": "A network administrator is troubleshooting connectivity issues on a server. Using a tester, the administrator notices that the signals generated by the server NIC are distorted and not usable. In which layer of the OSI model is the error categorized?", "o": ["presentation layer", "network layer", "physical layer", "data link layer"], "a": 2, "e": " The NIC has responsibilities in both Layer 1 and Layer 2. The NIC encodes the frame as a series of signals that are transmitted onto the local media. This is the responsibility of the physical layer of the OSI model. The signal could be in the form of electrical, optical, or radio waves."}, {"id": 59, "t": 2, "q": "A network administrator is measuring the transfer of bits across the company backbone for a mission critical financial application. The administrator notices that the network throughput appears lower than the bandwidth expected. Which three factors could influence the differences in throughput? (Choose three.)", "o": ["the amount of traffic that is currently crossing the network", "the sophistication of the encapsulation method applied to the data", "the type of traffic that is crossing the network", "the latency that is created by the number of network devices that the data is crossing", "the bandwidth of the WAN connection to the Internet", "the reliability of the gigabit Ethernet infrastructure of the backbone"], "a": [0, 2, 3], "e": " Throughput usually does not match the specified bandwidth of physical links due to multiple factors. These factors include, the amount of traffic, type of traffic, and latency created by the network devices the data has to cross."}, {"id": 60, "t": 2, "q": "What is a characteristic of the LLC sublayer?", "o": ["It provides the logical addressing required that identifies the device.", "It provides delimitation of data according to the physical signaling requirements of the medium.", "It places information in the frame allowing multiple Layer 3 protocols to use the same network interface and media.", "It defines software processes that provide services to the physical layer."], "a": 2, "e": " The Logical Link Control (LLC) defines the software processes that provide services to the network layer protocols. The information is placed by LLC in the frame and identifies which network layer protocol is being used for the frame. This information allows multiple Layer 3 protocols, such as IPv4 and IPv6, to utilize the same network interface and media."}, {"id": 61, "t": 2, "q": "A network team is comparing physical WAN topologies for connecting remote sites to a headquarters building. Which topology provides high availability and connects some, but not all, remote sites?", "o": ["mesh", "partial mesh", "hub and spoke", "point-to-point"], "a": 1, "e": " Partial mesh topologies provide high availability by interconnecting multiple remote sites, but do not require a connection between all remote sites. A mesh topology requires point-to-point links with every system being connected to every other system. A point-to-point topology is where each device is connected to one other device. A hub and spoke uses a central device in a star topology that connects to other point-to-point devices."}, {"id": 62, "t": 2, "q": "What are the three primary functions provided by Layer 2 data encapsulation? (Choose three.)", "o": ["error correction through a collision detection method", "session control using port numbers", "data link layer addressing", "placement and removal of frames from the media", "detection of errors through CRC calculations", "delimiting groups of bits into frames", "conversion of bits into data signals"], "a": [2, 4, 5], "e": " Through the framing process, delimiters are used to identify the start and end of the sequence of bits that make up a frame. Data link layer addressing is added to enable a frame to be delivered to a destination node. A cyclic redundancy check (CRC) field is calculated on every bit and added to the frame. If the CRC value contained in the arriving frame is the same as the one the receiving node creates, the frame will be processed."}, {"id": 63, "t": 2, "q": "What will a host on an Ethernet network do if it receives a frame with a destination MAC address that does not match its own MAC address?", "o": ["It will discard the frame.", "It will forward the frame to the next host.", "It will remove the frame from the media.", "It will strip off the data-link frame to check the destination IP address."], "a": 0, "e": " In an Ethernet network, each NIC in the network checks every arriving frame to see if the destination MAC address in the frame matches its own MAC address. If there is no match, the device discards the frame. If there is a match, the NIC passes the frame up to the next OSI layer."}, {"id": 64, "t": 2, "q": "What are two examples of the cut-through switching method? (Choose two.)", "o": ["store-and-forward switching", "fast-forward switching", "CRC switching", "fragment-free switching", "QOS switching"], "a": [1, 3], "e": " Store-and forward switching accepts the entire frame and performs error checking using CRC before forwarding the frame. Store-and-forward is often required for QOS analysis. Fast-forward and fragment-free are both variations of the cut-through switching method where only part of the frame is received before the switch begins to forward it."}, {"id": 65, "t": 3, "q": "What are two actions performed by a Cisco switch? (Choose two.)", "o": ["building a routing table that is based on the first IP address in the frame header", "using the source MAC addresses of frames to build and maintain a MAC address table", "forwarding frames with unknown destination IP addresses to the default gateway", "utilizing the MAC address table to forward frames via the destination MAC address", "examining the destination MAC address to add new entries to the MAC address table"], "a": [1, 3], "e": "Important actions that a switch performs are as follows: When a frame comes in, the switch examines the Layer 2 source address to build and maintain the Layer 2 MAC address table. It examines the Layer 2 destination address to determine how to forward the frame. When the destination address is in the MAC address table, then the frame is sent out a particular port. When the address is unknown, the frame is sent to all ports that have devices connected to that network."}, {"id": 66, "t": 2, "q": "Which frame forwarding method receives the entire frame and performs a CRC check to detect errors before forwarding the frame?", "o": ["cut-through switching", "store-and-forward switching", "fragment-free switching", "fast-forward switching"], "a": 1, "e": "Fast-forward and fragment-free switching are variations of cut-through switching, which begins to forward the frame before the entire frame is received."}, {"id": 67, "t": 3, "q": "Refer to the exhibit. If host A sends an IP packet to host B, what will the destination address be in the frame when it leaves host A? <i>(exhibit not shown)</i>", "o": ["DD:DD:DD:DD:DD:DD", "172.168.10.99", "CC:CC:CC:CC:CC:CC", "172.168.10.65", "BB:BB:BB:BB:BB:BB", "AA:AA:AA:AA:AA:AA"], "a": 4, "e": " When a host sends information to a distant network, the Layer 2 frame header will contain a source and destination MAC address. The source address will be the originating host device. The destination address will be the router interface that connects to the same network. In the case of host A sending information to host B, the source address is AA:AA:AA:AA:AA:AA and the destination address is the MAC address assigned to the R2 Ethernet interface, BB:BB:BB:BB:BB:BB."}, {"id": 68, "t": 3, "q": "What addresses are mapped by ARP?", "o": ["destination MAC address to a destination IPv4 address", "destination IPv4 address to the source MAC address", "destination IPv4 address to the destination host name", "destination MAC address to the source IPv4 address"], "a": 0, "e": " ARP, or the Address Resolution Protocol, works by mapping a destination MAC address to a destination IPv4 address. The host knows the destination IPv4 address and uses ARP to resolve the corresponding destination MAC address."}, {"id": 69, "t": 3, "q": "What information is added during encapsulation at OSI Layer 3?", "o": ["source and destination MAC", "source and destination application protocol", "source and destination port number", "source and destination IP address"], "a": 3, "e": " IP is a Layer 3 protocol. Layer 3 devices can open the Layer 3 header to inspect the Layer 3 header which contains IP-related information including the source and destination IP addresses."}, {"id": 70, "t": 3, "q": "What are two services provided by the OSI network layer? (Choose two.)", "o": ["performing error detection", "routing packets toward the destination", "encapsulating PDUs from the transport layer", "placement of frames on the media", "collision detection"], "a": [1, 2], "e": "The OSI network layer provides several services to allow communication between devices: addressing encapsulation routing de-encapsulation Error detection, placing frames on the media, and collision detection are all functions of the data ink layer."}, {"id": 71, "t": 3, "q": "Refer to the exhibit. The network administrator for a small advertising company has chosen to use the 192.168.5.96/27 network for internal LAN addressing. As shown in the exhibit, a static IP address is assigned to the company web server. However, the web server cannot access the Internet. The administrator verifies that local workstations with IP addresses that are assigned by a DHCP server can access the Internet, and the web server is able to ping local workstations. Which component is incorrectly configured? <i>(exhibit not shown)</i>", "o": ["subnet mask", "DNS address", "host IP address", "default gateway address"], "a": 3, "e": " When a 255.255.255.224 subnet mask is used, the first three bits of the last octet are part of the network portion for an IPv4 address in the subnet. For the 192.168.5.96/27 network, valid host addresses are 192.168.5.97 through 192.168.5.126. The default gateway address is for the Layer 3 device on the same network and it must contain an IP address within the valid IP address range."}, {"id": 72, "t": 3, "q": "Why does a Layer 3 device perform the ANDing process on a destination IP address and subnet mask?", "o": ["to identify the broadcast address of the destination network", "to identify the host address of the destination host", "to identify faulty frames", "to identify the network address of the destination network"], "a": 3, "e": " ANDing allows us to identify the network address from the IP address and the network mask."}, {"id": 73, "t": 1, "q": "What are two functions of NVRAM? (Choose two.)", "o": ["to store the routing table", "to retain contents when power is removed", "to store the startup configuration file", "to contain the running configuration file", "to store the ARP table"], "a": [1, 2], "e": "NVRAM is permanent memory storage, so the startup configuration file is preserved even if the router loses power."}, {"id": 74, "t": 1, "q": "Refer to the exhibit. What will be the result of entering this configuration the next time a network administrator connects a console cable to the router and no additional commands have been entered? <i>(exhibit not shown)</i>", "o": ["The administrator will be required to enter Cisco123.", "The administrator will be required to enter Cisco234.", "The administrator will be required to enter Cisco789.", "The administrator will be presented with the R1&gt; prompt."], "a": 3, "e": "Until both the password password and the login commands are entered in console line configuration mode, no password is required to gain access to enable mode."}, {"id": 75, "t": 3, "q": "What is the dotted decimal representation of the IPv4 address 11001011.00000000.01110001.11010011?", "o": ["192.0.2.199", "198.51.100.201", "203.0.113.211", "209.165.201.223"], "a": 2, "e": " Each section (octet) contains eight binary digits. Each digit represents a specific value (128, 64, 32, 16, 8, 4, 2, and 1). Everywhere there is a 1, the specific value is relevant. Add all relevant values in a particular octet to obtain the decimal value. For example binary 11001011 equals 203 in decimal."}, {"id": 76, "t": 3, "q": "What are three characteristics of multicast transmission? (Choose three.)", "o": ["The source address of a multicast transmission is in the range of 224.0.0.0 to 224.0.0.255.", "A single packet can be sent to a group of hosts.", "Multicast transmission can be used by routers to exchange routing information.", "Routers will not forward multicast addresses in the range of 224.0.0.0 to 224.0.0.255.", "Computers use multicast transmission to request IPv4 addresses.", "Multicast messages map lower layer addresses to upper layer addresses."], "a": [1, 2, 3], "e": " Broadcast messages consist of single packets that are sent to all hosts on a network segment. These types of messages are used to request IPv4 addresses, and map upper layer addresses to lower layer addresses. A multicast transmission is a single packet sent to a group of hosts and is used by routing protocols, such as OSPF and RIPv2, to exchange routes. The address range 224.0.0.0 to 224.0.0.255 is reserved for link-local addresses to reach multicast groups on a local network."}, {"id": 77, "t": 3, "q": "What are the three ranges of IP addresses that are reserved for internal private use? (Choose three.)", "o": ["10.0.0.0/8", "64.100.0.0/14", "127.16.0.0/12", "172.16.0.0/12", "192.31.7.0/24", "192.168.0.0/16"], "a": [0, 3, 5], "e": " The private IP address blocks that are used inside companies are as follows: 10.0.0.0 /8 (any address that starts with 10 in the first octet) 172.16.0.0 /12 (any address that starts with 172.16 in the first two octets through 172.31.255.255) 192.168.0.0 /16 (any address that starts with 192.168 in the first two octets)"}, {"id": 78, "t": 3, "q": "What purpose does NAT64 serve in IPv6?", "o": ["It converts IPv6 packets into IPv4 packets.", "It translates private IPv6 addresses into public IPv6 addresses.", "It enables companies to use IPv6 unique local addresses in the network.", "It converts regular IPv6 addresses into 64-bit addresses that can be used on the Internet.", "It converts the 48-bit MAC address into a 64-bit host address that can be used for automatic host addressing."], "a": 0, "e": " NAT64 is typically used in IPv6 when networks are being transitioned from IPv4 to IPv6. It allows the IPv6 networks to connect to IPv4 networks (such as the Internet), and works by translating the IPv6 packets into IPv4 packets."}, {"id": 79, "t": 3, "q": "Which range of link-local addresses can be assigned to an IPv6-enabled interface?", "o": ["FEC0::/10", "FDEE::/7", "FE80::/10", "FF00::/8"], "a": 2, "e": " Link-local addresses are in the range of FE80::/10 to FEBF::/10. The original IPv6 specification defined site-local addresses and used the prefix range FEC0::/10, but these addresses were deprecated by the IETF in favor of unique local addresses. FDEE::/7 is a unique local address because it is in the range of FC00::/7 to FDFF::/7. IPv6 multicast addresses have the prefix FF00::/8."}, {"id": 80, "t": 3, "q": "Which three addresses are valid public addresses? (Choose three.)", "o": ["198.133.219.17", "192.168.1.245", "10.15.250.5", "128.107.12.117", "192.15.301.240", "64.104.78.227"], "a": [0, 3, 5], "e": "The ranges of private IPv4 addresses are as folllows: 10.0.0.0 – 10.255.255.255 172.16.0.0 – 172.31.255.255 192.168.0.0 – 192.168.255.255"}, {"id": 81, "t": 3, "q": "Refer to the exhibit. On the basis of the output, which two statements about network connectivity are correct? (Choose two.) <i>(exhibit not shown)</i>", "o": ["There is connectivity between this device and the device at 192.168.100.1.", "The connectivity between these two hosts allows for videoconferencing calls.", "There are 4 hops between this device and the device at 192.168.100.1.", "The average transmission time between the two hosts is 2 milliseconds.", "This host does not have a default gateway configured."], "a": [0, 2], "e": " The output displays a successful Layer 3 connection between a host computer and a host at 19.168.100.1. It can be determined that 4 hops exist between them and the average transmission time is 1 milliseconds. Layer 3 connectivity does not necessarily mean that an application can run between the hosts."}, {"id": 82, "t": 3, "q": "How many valid host addresses are available on an IPv4 subnet that is configured with a /26 mask?", "o": ["254", "190", "192", "62", "64"], "a": 3, "e": " When a /26 mask is used, 6 bits are used as host bits. With 6 bits, 64 addresses are possible, but one address is for the subnet number and one address is for a broadcast. This leaves 62 addresses that can be assigned to network devices."}, {"id": 83, "t": 3, "q": "A site administrator has been told that a particular network at the site must accommodate 126 hosts. Which subnet mask would be used that contains the required number of host bits?", "o": ["255.255.255.0", "255.255.255.128", "255.255.255.224", "255.255.255.240"], "a": 1, "e": " The subnet mask of 255.255.255.0 has 8 host bits. The mask of 255.255.255.128 results in 7 host bits. The mask of 255.255.255.224 has 5 host bits. Finally, 255.255.255.240 represents 4 host bits."}, {"id": 84, "t": 3, "q": "A network administrator wants to have the same subnet mask for three subnetworks at a small site. The site has the following networks and numbers of devices:<br>Subnetwork A: IP phones – 10 addresses<br>Subnetwork B: PCs – 8 addresses<br>Subnetwork C: Printers – 2 addresses<br>What single subnet mask would be appropriate to use for the three subnetworks?", "o": ["255.255.255.0", "255.255.255.240", "255.255.255.248", "255.255.255.252"], "a": 1, "e": " If the same mask is to be used, then the network with the most hosts must be examined for number of hosts. Because this is 10 hosts, 4 host bits are needed. The /28 or 255.255.255.240 subnet mask would be appropriate to use for these networks."}, {"id": 85, "t": 3, "q": "Which subnet would include the address 192.168.1.96 as a usable host address?", "o": ["192.168.1.64/26", "192.168.1.32/27", "192.168.1.32/28", "192.168.1.64/29"], "a": 0, "e": " For the subnet of 192.168.1.64/26, there are 6 bits for host addresses, yielding 64 possible addresses. However, the first and last subnets are the network and broadcast addresses for this subnet. Therefore, the range of host addresses for this subnet is 192.168.1.65 to 192.168.1.126. The other subnets do not contain the address 192.168.1.96 as a valid host address."}, {"id": 86, "t": 3, "q": "What subnet mask is needed if an IPv4 network has 40 devices that need IP addresses and address space is not to be wasted?", "o": ["255.255.255.0", "255.255.255.128", "255.255.255.192", "255.255.255.224", "255.255.255.240"], "a": 2, "e": " In order to accommodate 40 devices, 6 host bits are needed. With 6 bits, 64 addresses are possible, but one address is for the subnet number and one address is for a broadcast. This leaves 62 addresses that can be assigned to network devices. The mask associated with leaving 6 host bits for addressing is 255.255.255.192."}, {"id": 87, "t": 4, "q": "What are two characteristics shared by TCP and UDP? (Choose two.)", "o": ["default window size", "connectionless communication", "port numbering", "3-way handshake", "ability to to carry digitized voice", "use of checksum"], "a": [2, 5], "e": " Both TCP and UDP use source and destination port numbers to distinguish different data streams and to forward the right data segments to the right applications. Error checking the header and data is done by both protocols by using a checksum calculation to determine the integrity of the data that is received. TCP is connection-oriented and uses a 3-way handshake to establish an initial connection. TCP also uses window to regulate the amount of traffic sent before receiving an acknowledgment. UDP is connectionless and is the best protocol for carry digitized VoIP signals."}, {"id": 88, "t": 4, "q": "Why are port numbers included in the TCP header of a segment?", "o": ["to indicate the correct router interface that should be used to forward a segment", "to identify which switch ports should receive or forward the segment", "to determine which Layer 3 protocol should be used to encapsulate the data", "to enable a receiving host to forward the data to the appropriate application", "to allow the receiving host to assemble the packet in the proper order"], "a": 3, "e": "✔ to enable a receiving host to forward the data to the appropriate application"}, {"id": 89, "t": 3, "q": "Refer to the exhibit. Consider the IP address of 192.168.10.0/24 that has been assigned to a high school building. The largest network in this building has 100 devices. If 192.168.10.0 is the network number for the largest network, what would be the network number for the next largest network, which has 40 devices? <i>(exhibit not shown)</i>", "o": ["192.168.10.0", "192.168.10.128", "192.168.10.192", "192.168.10.224", "192.168.10.240"], "a": 1, "e": " The first thing to calculate is what IP addresses are used by the largest LAN. Because the LAN has 100 hosts, 7 bits must be left for host bits. This would be a subnet mask of 255.255.255.128 for the largest LAN (192.168.10.0/25). The IP addresses range from 192.168.10.0 through 192.168.10.127. 192.168.10.0 is the network number (all 0s in the host bits) and 192.168.10.127 is the broadcast for this Ethernet LAN (all 1s in the host bits). The next available IP address is the next network number – 192.168.10.128."}, {"id": 90, "t": 3, "q": "Which statement is true about variable-length subnet masking?", "o": ["Each subnet is the same size.", "The size of each subnet may be different, depending on requirements.", "Subnets may only be subnetted one additional time.", "Bits are returned, rather than borrowed, to create additional subnets."], "a": 1, "e": " In variable-length subnet masking, bits are borrowed to create subnets. Additional bits may be borrowed to create additional subnets within the original subnets. This may continue until there are no bits available to borrow."}, {"id": 91, "t": 4, "q": "In what two situations would UDP be the preferred transport protocol over TCP? (Choose two.)", "o": ["when applications need to guarantee that a packet arrives intact, in sequence, and unduplicated", "when a faster delivery mechanism is needed", "when delivery overhead is not an issue", "when applications do not need to guarantee delivery of the data", "when destination port numbers are dynamic"], "a": [1, 3], "e": " UDP is a stateless protocol, which means that neither device on either end of the conversation must keep track of the conversation. As a stateless protocol, UDP is used as the Layer 4 protocol for applications that need speedy (best-effort) delivery. An example of such traffic is the transport of digitized voice or video."}, {"id": 92, "t": 3, "q": "What important information is added to the TCP/IP transport layer header to ensure communication and connectivity with a remote network device?", "o": ["timing and synchronization", "destination and source port numbers", "destination and source physical addresses", "destination and source logical network addresses"], "a": 1, "e": " The destination and source port numbers are used to identify exactly which protocol and process is requesting or responding to a request."}, {"id": 93, "t": 4, "q": "What is the TCP mechanism used in congestion avoidance?", "o": ["three-way handshake", "socket pair", "two-way handshake", "sliding window"], "a": 3, "e": " TCP uses windows to attempt to manage the rate of transmission to the maximum flow that the network and destination device can support while minimizing loss and retransmissions. When overwhelmed with data, the destination can send a request to reduce the of the window. This congestion avoidance is called sliding windows."}, {"id": 94, "t": 3, "q": "Which scenario describes a function provided by the transport layer?", "o": ["A student is using a classroom VoIP phone to call home. The unique identifier burned into the phone is a transport layer address used to contact another network device on the same network.", "A student is playing a short web-based movie with sound. The movie and sound are encoded within the transport layer header.", "A student has two web browser windows open in order to access two web sites. The transport layer ensures the correct web page is delivered to the correct browser window.", "A corporate worker is accessing a web server located on a corporate network. The transport layer formats the screen so the web page appears properly no matter what device is being used to view the web site."], "a": 2, "e": " The source and destination port numbers are used to identify the correct application and window within that application."}, {"id": 95, "t": 3, "q": "A user opens three browsers on the same PC to access www.cisco.com to search for certification course information. The Cisco web server sends a datagram as a reply to the request from one of the web browsers. Which information is used by the TCP/IP protocol stack in the PC to identify which of the three web browsers should receive the reply?", "o": ["the destination IP address", "the destination port number", "the source IP address", "the source port number"], "a": 1, "e": " Each web browser client application opens a randomly generated port number in the range of the registered ports and uses this number as the source port number in the datagram that it sends to a server. The server then uses this port number as the destination port number in the reply datagram that it sends to the web browser. The PC that is running the web browser application receives the datagram and uses the destination port number that is contained in this datagram to identify the client application."}, {"id": 96, "t": 4, "q": "What are two ways that TCP uses the sequence numbers in a segment? (Choose two.)", "o": ["to identify missing segments at the destination", "to reassemble the segments at the remote location", "to specify the order in which the segments travel from source to destination", "to limit the number of segments that can be sent out of an interface at one time", "to determine if the packet changed during transit"], "a": [0, 1], "e": "✔ to identify missing segments at the destination; to reassemble the segments at the remote location"}, {"id": 97, "t": 3, "q": "Which two tasks are functions of the presentation layer? (Choose two.)", "o": ["compression", "addressing", "encryption", "session control", "authentication"], "a": [0, 2], "e": " The presentation layer deals with common data format. Encryption, formatting, and compression are some of the functions of the layer. Addressing occurs in the network layer, session control occurs in the session layer, and authentication takes place in the application or session layer."}, {"id": 98, "t": 4, "q": "Which three statements characterize UDP? (Choose three.)", "o": ["UDP provides basic connectionless transport layer functions.", "UDP provides connection-oriented, fast transport of data at Layer 3.", "UDP relies on application layer protocols for error detection.", "UDP is a low overhead protocol that does not provide sequencing or flow control mechanisms.", "UDP relies on IP for error detection and recovery.", "UDP provides sophisticated flow control mechanisms."], "a": [0, 2, 3], "e": " UDP is a simple protocol that provides the basic transport layer functions. It has much lower overhead than TCP because it is not connection-oriented and does not offer the sophisticated retransmission, sequencing, and flow control mechanisms that provide reliability."}, {"id": 99, "t": 2, "q": "What is a key characteristic of the peer-to-peer networking model?", "o": ["wireless networking", "social networking without the Internet", "network printing using a print server", "resource sharing without a dedicated server"], "a": 3, "e": " The peer-to-peer (P2P) networking model allows data, printer, and resource sharing without a dedicated server."}, {"id": 100, "t": 3, "q": "A technician can ping the IP address of the web server of a remote company but cannot successfully ping the URL address of the same web server. Which software utility can the technician use to diagnose the problem?", "o": ["tracert", "ipconfig", "netstat", "nslookup"], "a": 3, "e": " Traceroute (tracert) is a utility that generates a list of hops that were successfully reached along the path from source to destination.This list can provide important verification and troubleshooting information. The ipconfig utility is used to display the IP configuration settings on a Windows PC. The Netstat utility is used to identify which active TCP connections are open and running on a networked host. Nslookup is a utility that allows the user to manually query the name servers to resolve a given host name. This utility can also be used to troubleshoot name resolution issues and to verify the current status of the name servers."}, {"id": 101, "t": 0, "q": "Which domain name would be an example of a top-level domain?", "o": ["www.cisco.com", "cisco.com", ".com", "root.cisco.com"], "a": 2, "e": " Top-level domains represent a country or type of organization, such as .com or .edu."}, {"id": 102, "t": 3, "q": "A PC obtains its IP address from a DHCP server. If the PC is taken off the network for repair, what happens to the IP address configuration?", "o": ["The configuration is permanent and nothing changes.", "The address lease is automatically renewed until the PC is returned.", "The address is returned to the pool for reuse when the lease expires.", "The configuration is held by the server to be reissued when the PC is returned."], "a": 2, "e": " When a DCHP address is issued to a host, it is for a specific lease time. Once the lease expires, the address is returned to the DHCP pool."}, {"id": 103, "t": 4, "q": "When planning for network growth, where in the network should packet captures take place to assess network traffic?", "o": ["on as many different network segments as possible", "only at the edge of the network", "between hosts and the default gateway", "only on the busiest network segment"], "a": 0, "e": " Because some types of traffic will be only on specific network segments, packet captures for analysis should be performed on as many segments as possible."}, {"id": 104, "t": 4, "q": "A wireless host needs to request an IP address. What protocol would be used to process the request?", "o": ["FTP", "HTTP", "DHCP", "ICMP", "SNMP"], "a": 2, "e": " The DHCP protocol is used to request, issue, and manage IP addressing information. CSMA/CD is the access method used with wired Ethernet. ICMP is used to test connectivity. SNMP is used with network management and FTP is used for file transfer."}, {"id": 105, "t": 2, "q": "A network technician suspects that a particular network connection between two Cisco switches is having a duplex mismatch. Which command would the technician use to see the Layer 1 and Layer 2 details of a switch port?", "o": ["show mac-address-table", "show ip interface brief", "show interfaces", "show running-config"], "a": 2, "e": " The show interfaces command can be used on both routers and switches to see speed, duplex, media type, MAC address, port type, and other Layer 1/Layer 2-related information."}, {"id": 106, "t": 4, "q": "A user is unable to reach the web site when typing http://www.cisco.com in a web browser, but can reach the same site by typing http://72.163.4.161. What is the issue?", "o": ["default gateway", "DHCP", "TCP/IP protocol stack", "DNS"], "a": 3, "e": " Domain Name Service (DNS) is used to translate a web address to an IP address. The address of the DNS server is provided via DHCP to host computers."}, {"id": 107, "t": 3, "q": "A company is expanding its business to other countries. All branch offices must remain connected to corporate headquarters at all times. Which network technology is required to support this requirement?", "o": ["LAN", "MAN", "WAN", "WLAN"], "a": 2, "e": " A local-area network (LAN) normally connects end users and network resources over a limited geographic area using Ethernet technology. A wireless LAN (WLAN) serves the same purpose as a LAN but uses wireless technologies. A metropolitan-area network (MAN) spans a larger geographic area such as a city, and a wide-area network (WAN) connects networks together over a large geographic area. WANs can span cities, countries, or the globe."}, {"id": 108, "t": 2, "q": "A home user is looking for an ISP connection that provides high speed digital transmission over regular phone lines. What ISP connection type should be used?", "o": ["DSL", "dial-up", "satellite", "cell modem", "cable modem"], "a": 0, "e": "DSL is the best technology to use over existing phone lines. A lot of ISPs have a lookup on their website where you can enter your phone number and see if they can offer you service."}, {"id": 109, "t": 1, "q": "How does quality of service help a network support a wide range of applications and services?", "o": ["by limiting the impact of a network failure", "by allowing quick recovery from network failures", "by providing mechanisms to manage congested network traffic", "by providing the ability for the network to grow to accommodate new users"], "a": 2, "e": " Quality of service (QoS), is a vital component of the architecture of a network. With QoS, network administrators can provide applications with predictable and measurable service guarantees through mechanisms that manage congested network traffic."}, {"id": 110, "t": 3, "q": "What source IP address does a router use by default when the traceroute command is issued?", "o": ["the highest configured IP address on the router", "the lowest configured IP address on the router", "a loopback IP address", "the IP address of the outbound interface"], "a": 3, "e": " When sending an echo request message, a router will use the IP address of the exit interface as the source IP address. This default behavior can be changed by using an extended ping and specifying a specific source IP address."}, {"id": 111, "t": 1, "q": "After making configuration changes on a Cisco switch, a network administrator issues a copy running-config startup-config command. What is the result of issuing this command?", "o": ["The new configuration will be stored in flash memory.", "The new configuration will be loaded if the switch is restarted.", "The current IOS file will be replaced with the newly configured file.", "The configuration changes will be removed and the original configuration will be restored."], "a": 1, "e": " With the copy running-config startup-config command, the content of the current operating configuration replaces the startup configuration file stored in NVRAM. The configuration file saved in NVRAM will be loaded when the device is restarted."}, {"id": 112, "t": 1, "q": "Refer to the exhibit. A network administrator is configuring access control to switch SW1. If the administrator has already logged into a Telnet session on the switch, which password is needed to access privileged EXEC mode? <i>(exhibit not shown)</i>", "o": ["letmein", "secretin", "lineconin", "linevtyin"], "a": 1, "e": " Telnet accesses a network device through the virtual interface configured with the line VTY command. The password configured under this is required to access the user EXEC mode. The password configured under the line console 0 command is required to gain entry through the console port, and the enable and enable secret passwords are used to allow entry into the privileged EXEC mode."}, {"id": 113, "t": 1, "q": "Which statement accurately describes a TCP/IP encapsulation process when a PC is sending data to the network?", "o": ["Data is sent from the internet layer to the network access layer.", "Packets are sent from the network access layer to the transport layer.", "Segments are sent from the transport layer to the internet layer.", "Frames are sent from the network access layer to the internet layer."], "a": 2, "e": " When the data is traveling from the PC to the network, the transport layer sends segments to the internet layer. The internet layer sends packets to the network access layer, which creates frames and then converts the frames to bits. The bits are released to the network media."}, {"id": 114, "t": 3, "q": "What unique address is embedded in an Ethernet NIC and used for communication on an Ethernet network?", "o": ["host address", "IP address", "MAC address", "network address", "k layer"], "a": 2, "e": " The MAC address is a 48-bit address that is burned into every Ethernet NIC. Each MAC address is unique throughout the world."}, {"id": 115, "t": 3, "q": "During the encapsulation process, what occurs at the data link layer for a PC connected to an Ethernet network?", "o": ["An IP address is added.", "The logical address is added.", "The physical address is added.", "The process port number is added."], "a": 2, "e": " The Ethernet frame includes the source and destination physical address. The trailer includes a CRC value in the Frame Check Sequence field to allow the receiving device to determine if the frame has been changed (has errors) during the transmission."}, {"id": 116, "t": 2, "q": "What are two characteristics of Ethernet MAC addresses? (Choose two.)", "o": ["They are globally unique.", "They are routable on the Internet.", "They are expressed as 12 hexadecimal digits.", "MAC addresses use a flexible hierarchical structure.", "MAC addresses must be unique for both Ethernet and serial interfaces on a device."], "a": [0, 2], "e": " An Ethernet MAC address is a 48-bit binary value expressed as 12 hexadecimal digits. MAC addresses must be globally unique by design. MAC addresses are in flat structure and thus they are not routable on the Internet. Serial interfaces do not use MAC addresses."}, {"id": 117, "t": 3, "q": "Under which two circumstances will a switch flood a frame out of every port except the port that the frame was received on? (Choose two.)", "o": ["The frame has the broadcast address as the destination address.", "The destination address is unknown to the switch.", "The source address in the frame header is the broadcast address.", "The source address in the frame is a multicast address.", "The destination address in the frame is a known unicast address."], "a": [0, 1], "e": " A switch will flood a frame out of every port, except the one that the frame was received from, under two circumstances. Either the frame has the broadcast address as the destination address, or the destination address is unknown to the switch."}, {"id": 118, "t": 1, "q": "Which two commands can be used on a Windows host to display the routing table? (Choose two.)", "o": ["netstat -s", "route print", "show ip route", "netstat -r", "tracert"], "a": [1, 3], "e": " On a Windows host, the route print or netstat -r commands can be used to display the host routing table. Both commands generate the same output. On a router, the show ip route command is used to display the routing table. The netstat –scommand is used to display per-protocol statistics. The tracert command is used to display the path that a packet travels to its destination."}, {"id": 119, "t": 4, "q": "Which two functions are primary functions of a router? (Choose two.)", "o": ["packet forwarding", "microsegmentation", "domain name resolution", "path selection", "flow control"], "a": [0, 3], "e": "A router accepts a packet and accesses its routing table to determine the appropriate exit interface based on the destination address. The router then forwards the packet out of that interface."}, {"id": 120, "t": 3, "q": "What is the binary representation of 0xCA?", "o": ["10111010", "11010101", "11001010", "11011010"], "a": 2, "e": " When converted, CA in hex is equivalent to 11011010 in binary. One way to do the conversion is one nibble at a time, C = 1100 and A = 1010. Combine the two nibbles gives 11001010."}, {"id": 121, "t": 3, "q": "Which service provides dynamic global IPv6 addressing to end devices without using a server that keeps a record of available IPv6 addresses?", "o": ["stateful DHCPv6", "SLAAC", "static IPv6 addressing", "stateless DHCPv6"], "a": 1, "e": " Using stateless address autoconfiguration (SLAAC), a PC can solicit a router and receive the prefix length of the network. From this information the PC can then create its own IPv6 global unicast address."}, {"id": 122, "t": 3, "q": "What is the purpose of the command ping ::1?", "o": ["It tests the internal configuration of an IPv6 host.", "It tests the broadcast capability of all hosts on the subnet.", "It tests the multicast connectivity to all hosts on the subnet.", "It tests the reachability of the default gateway for the network."], "a": 0, "e": " The address ::1 is an IPv6 loopback address. Using the command ping ::1 tests the internal IP stack to ensure that it is configured and functioning correctly. It does not test reachability to any external device, nor does it confirm that IPv6 addresses are properly configured on the host."}, {"id": 123, "t": 3, "q": "How many usable IP addresses are available on the 192.168.1.0/27 network?", "o": ["256", "254", "62", "30", "16", "32"], "a": 3, "e": " A /27 mask is the same as 255.255.255.224. This leaves 5 host bits. With 5 host bits, 32 IP addresses are possible, but one address represents the subnet number and one address represents the broadcast address. Thus, 30 addresses can then be used to assign to network devices."}, {"id": 124, "t": 4, "q": "What is the process of dividing a data stream into smaller pieces before transmission?", "o": ["segmentation", "encapsulation", "encoding", "flow control"], "a": 0, "e": " Data streams would cause significant network congestion if they were transmitted as a single large stream of bits. To increase efficiency, data streams are segmented into smaller more manageable pieces which are then transmitted over the network."}, {"id": 125, "t": 3, "q": "When IPv4 addressing is manually configured on a web server, which property of the IPv4 configuration identifies the network and host portion for an IPv4 address?", "o": ["DNS server address", "subnet mask", "default gateway", "DHCP server address"], "a": 1, "e": "There are several components that need to be entered when configuring IPv4 for an end device: IPv4 address - uniquely identifies an end device on the network Subnet mask - determines the network address portion and host portion for an IPv4 address Default gateway - the IP address of the router interface used for communicating with hosts in another network DNS server address - the IP address of the Domain Name System (DNS) server DHCP server address (if DHCP is used) is not configured manually on end devices. It will be provided by a DHCP server when an end device requests an IP address."}, {"id": 126, "t": 1, "q": "Which two roles can a computer assume in a peer-to-peer network where a file is being shared between two computers? (Choose two.)", "o": ["client", "master", "server", "slave", "transient"], "a": [0, 2], "e": " In a peer-to-peer (P2P) network, two or more computers are connected and can share resources without the use of a dedicated server. The computer that has the file acts as a server for the device (the client) that requests the file."}, {"id": 127, "t": 4, "q": "Which two protocols operate at the highest layer of the TCP/IP protocol stack? (Choose two.)", "o": ["DNS", "Ethernet", "IP", "POP", "TCP", "UDP"], "a": [0, 3], "e": " The application layer is the top layer of the TCP/IP protocol stack. Application layer protocols include HTTP, DNS, HTML, TFTP, POP, IMAP, FTP, and SMTP."}, {"id": 128, "t": 1, "q": "What is one difference between the client-server and peer-to-peer network models?", "o": ["Only in the client-server model can file transfers occur.", "Every device in a peer-to-peer network can function as a client or a server.", "A peer-to-peer network transfers data faster than a transfer using a client-server network.", "A data transfer that uses a device serving in a client role requires that a dedicated server be present."], "a": 1, "e": " Data transfer speeds depend on a number of factors including the amount of traffic, the quality of service imposed, and the network media. Transfer speeds are not dependent on the network model type. File transfers can occur using the client-server model or the peer-to-peer model. A data transfer between a device acting in the client role and a device acting in the server role can occur in both peer-to-peer and client-server networks."}, {"id": 129, "t": 1, "q": "What is the function of the HTTP GET message?", "o": ["to request an HTML page from a web server", "to send error information from a web server to a web client", "to upload content to a web server from a web client", "to retrieve client email from an email server using TCP port 110"], "a": 0, "e": " There are three common HTTP message types: GET – used by clients to request data from the web server POST – used by clients to upload data to a web server PUT – used by clients to upload data to a web server"}, {"id": 130, "t": 1, "q": "Which networking model is being used when an author uploads one chapter document to a file server of a book publisher?", "o": ["peer-to-peer", "master-slave", "client/server", "point-to-point"], "a": 2, "e": " In the client/server network model, a network device assumes the role of server in order to provide a particular service such as file transfer and storage. In the client/server network model, a dedicated server does not have to be used, but if one is present, the network model being used is the client/server model. In contrast, a peer-to-peer network does not have a dedicated server."}, {"id": 131, "t": 4, "q": "What network service resolves the URL entered on a PC to the IP address of the destination server?", "o": ["DNS", "DHCP", "FTP", "SNMP"], "a": 0, "e": " When a client attempts to connect to a website, the destination URL must be resolved to an IP address. To do this the client queries a Domain Name System (DNS) server."}, {"id": 132, "t": 1, "q": "A network engineer is analyzing reports from a recently performed network baseline. Which situation would depict a possible latency issue?", "o": ["a change in the bandwidth according to the show interfaces output", "a next-hop timeout from a traceroute", "an increase in host-to-host ping response times", "a change in the amount of RAM according to the show version output"], "a": 2, "e": " While analyzing historical reports an administrator can compare host-to-host timers from the ping command and depict possible latency issues."}, {"id": 133, "t": 3, "q": "Which firewall feature is used to ensure that packets coming into a network are legitimate responses to requests initiated from internal hosts?", "o": ["stateful packet inspection", "URL filtering", "application filtering", "packet filtering"], "a": 0, "e": " Stateful packet inspection on a firewall checks that incoming packets are actually legitimate responses to requests originating from hosts inside the network. Packet filtering can be used to permit or deny access to resources based on IP or MAC address. Application filtering can permit or deny access based on port number. URL filtering is used to permit or deny access based on URL or on keywords."}, {"id": 134, "t": 3, "q": "What is one indication that a Windows computer did not receive an IPv4 address from a DHCP server?", "o": ["The computer cannot ping 127.0.0.1.", "Windows displays a DHCP timeout message.", "The computer receives an IP address that starts with 169.254", "The computer cannot ping other devices on the same network with IP addresses in the 169.254.0.0/16 range."], "a": 2, "e": " When a Windows PC cannot communicate with an IPv4 DHCP server, the computer automatically assigns an IP address in the 169.254.0.0/16 range. Any other device on the same network that receives an address in the same range is reachable."}, {"id": 135, "t": 1, "q": "Which command can an administrator issue on a Cisco router to send debug messages to the vty lines?", "o": ["terminal monitor", "logging console", "logging buffered", "logging synchronous"], "a": 0, "e": " Debug messages, like other IOS log messages, are sent to the console line by default. Sending these messages to the terminal lines requires the terminal monitor command."}, {"id": 136, "t": 2, "q": "A medium-sized business is researching available options for connecting to the Internet. The company is looking for a high speed option with dedicated, symmetric access. Which connection type should the company choose?", "o": ["DSL", "dialup", "satellite", "leased line", "cable modem"], "a": 3, "e": "✔ leased line"}, {"id": 137, "t": 0, "q": "What characteristic of a network enables it to quickly grow to support new users and applications without impacting the performance of the service being delivered to existing users?", "o": ["reliability", "scalability", "quality of service", "accessibility"], "a": 1, "e": " Networks must be able to quickly grow to support new users and services, without impacting existing users and services. This ability to grow is known as scalability."}, {"id": 138, "t": 1, "q": "After several configuration changes are made to a router, the copy running-configuration startup-configuration command is issued. Where will the changes be stored?", "o": ["flash", "ROM", "NVRAM", "RAM", "the configuration register", "a TFTP server"], "a": 2, "e": "When changes are made to the running-config file, it should be saved to NVRAM as the startup configuration file in case the router is restarted or loses power. The following command saves the configuration to NVRAM: copy running-config startup-config"}, {"id": 139, "t": 1, "q": "Refer to the exhibit. From global configuration mode, an administrator is attempting to create a message-of-the-day banner by using the command banner motd V Authorized access only! Violators will be prosecuted! V When users log in using Telnet, the banner does not appear correctly. What is the problem? <i>(exhibit not shown)</i>", "o": ["The banner message is too long.", "The delimiting character appears in the banner message.", "The symbol “!” signals the end of a banner message.", "Message-of-the-day banners will only appear when a user logs in through the console port."], "a": 1, "e": "To create a banner message of the day on a device, use the banner motd # the message of the day # global config command. The \"#\" in the command syntax is called the delimiting character. It is entered before and after the message. The delimiting character can be any character as long as it does not occur in the message."}, {"id": 140, "t": 2, "q": "What are three characteristics of an SVI? (Choose three.)", "o": ["It is designed as a security protocol to protect switch ports.", "It is not associated with any physical interface on a switch.", "It is a special interface that allows connectivity by different types of media.", "It is required to allow connectivity by any device at any location.", "It provides a means to remotely manage a switch.", "It is associated with VLAN1 by default."], "a": [1, 4, 5], "e": " Switches have one or more switch virtual interfaces (SVIs). SVIs are created in software since there is no physical hardware associated with them. Virtual interfaces provide a means to remotely manage a switch over a network that is using IP. Each switch comes with one SVI appearing in the default configuration “out-of-the-box.” The default SVI interface is VLAN1."}, {"id": 141, "t": 1, "q": "A technician configures a switch with these commands:<br>Copy<br>SwitchA(config)# interface vlan 1<br>SwitchA(config-if)# ip address 192.168.1.1 255.255.255.0<br>SwitchA(config-if)# no shutdown<br>What is the technician configuring?", "o": ["Telnet access", "SVI", "password encryption", "physical switchport access"], "a": 1, "e": " For a switch to have an IP address, a switch virtual interface must be configured. This allows the switch to be managed remotely over the network."}, {"id": 142, "t": 2, "q": "In computer communication, what is the purpose of message encoding?", "o": ["to convert information to the appropriate form for transmission", "to interpret information", "to break large messages into smaller frames", "to negotiate correct timing for successful communication"], "a": 0, "e": " Before a message is sent across a network it must first be encoded. Encoding is the process of converting the data message into another format suitable for transmission across the physical medium. Each bit of the message is encoded into a pattern of sounds, light waves, or electrical impulses depending on the network media over which the bits are transmitted. The destination host receives and decodes the signals in order to interpret the message."}, {"id": 143, "t": 3, "q": "What is a characteristic of multicast messages?", "o": ["They are sent to a select group of hosts.", "They must be acknowledged.", "They are sent to a single destination.", "They are sent to all hosts on a network."], "a": 0, "e": " Multicast is a one-to-many type of communication. Multicast messages are addressed to a specific multicast group."}, {"id": 144, "t": 1, "q": "A large corporation has modified its network to allow users to access network resources from their personal laptops and smart phones. Which networking trend does this describe?", "o": ["bring your own device", "video conferencing", "online collaboration", "cloud computing"], "a": 0, "e": " BYOD allows end users to use personal tools to access the corporate network. Allowing this trend can have major impacts on a network, such as security and compatibility with corporate software and devices."}, {"id": 145, "t": 0, "q": "True or False.<br>A dedicated server is not needed when implementing a peer-to-peer network.", "o": ["true", "false"], "a": 0, "e": "✔ true"}, {"id": 146, "t": 3, "q": "What subnet mask is required to support 512 subnets on networks 172.28.0.0/16?", "o": ["255.255.240.0", "255.255.255.224", "255.255.255.240", "255.255.255.128", "255.255.252.0"], "a": 3, "e": "✔ 255.255.255.128"}, {"id": 147, "t": 3, "q": "A DHCP server is used to IP addresses dynamically to the hosts on a network. The address pool is configured with 10.29.244.0/25. There are 19 printers on this network that need to use reserve static IP addresses from the pool. How many IP address in the pool are left to be assign to other hosts?", "o": ["210", "60", "109", "107", "146"], "a": 3, "e": "✔ 107"}, {"id": 148, "t": 3, "q": "What is a function of the data link layer?", "o": ["provides the formatting of data", "provides for the exchange of data over a common local media", "provides end-to-end delivery of data between hosts", "provides delivery of data between two applications"], "a": 1, "e": "✔ provides for the exchange of data over a common local media"}, {"id": 149, "t": 4, "q": "Which communication tool allows real-time collaboration?", "o": ["wiki", "e-mail", "weblog", "instant messaging"], "a": 3, "e": "✔ instant messaging"}, {"id": 150, "t": 3, "q": "A host is accessing a Web server on a remote network. Which three functions are performed by intermediary network devices during this conversation? (Choose three.)", "o": ["regenerating data signals", "acting as a client or a server", "providing a channel over which messages travel", "applying security settings to control the flow of data", "notifying other devices when errors occur", "serving as the source or destination of the messages"], "a": [0, 3, 4], "e": "✔ regenerating data signals; applying security settings to control the flow of data; notifying other devices when errors occur"}, {"id": 151, "t": 1, "q": "Refer to the exhibit. From which location did this router load the IOS? <i>(exhibit not shown)</i>", "o": ["flash memory", "NVRAM", "RAM", "ROM", "a TFTP server"], "a": 0, "e": "In the provided show version output, the line System image file is \"flash:c1841-advipservicesk9-mz.124-15.Tl.bin\" explicitly identifies the source of the Cisco IOS. The prefix flash: indicates that the router successfully located and loaded the operating system image from its internal flash memory during the boot process. Additionally, the configuration register value of 0x2102 confirms the router is set to follow standard boot procedures, which typically involve loading the first valid IOS image found in flash if no other specific boot instructions are present."}, {"id": 152, "t": 1, "q": "Refer to the exhibit. An administrator is trying to configure the switch but receives the error message that is displayed in the exhibit. What is the problem? <i>(exhibit not shown)</i>", "o": ["The entire command, configure terminal, must be used.", "The administrator is already in global configuration mode.", "The administrator must first enter privileged EXEC mode before issuing the command.", "The administrator must connect via the console port to access global configuration mode."], "a": 2, "e": " In order to enter global configuration mode, the command configure terminal, or a shortened version such as config t, must be entered from privileged EXEC mode. In this scenario the administrator is in user EXEC mode, as indicated by the &gt; symbol after the hostname. The administrator would need to use the enable command to move into privileged EXEC mode before entering the configure terminal command."}, {"id": 153, "t": 4, "q": "A network administrator is upgrading a small business network to give high priority to real-time applications traffic. What two types of network services is the network administrator trying to accommodate? (Choose two.)", "o": ["SNMP", "instant messaging", "voice", "FTP", "video"], "a": [2, 4], "e": " Streaming media, such as video, and voice traffic, are both examples of real-time traffic. Real-time traffic needs higher priority through the network than other types of traffic because it is very sensitive to network delay and latency."}, {"id": 154, "t": 3, "q": "Which IPv4 address can be pinged to test the internal TCP/IP operation of a host?", "o": ["0.0.0.0", "0.0.0.1", "127.0.0.1", "192.168.1.1", "255.255.255.255"], "a": 2, "e": "✔ 127.0.0.1"}, {"id": 155, "t": 4, "q": "What three application layer protocols are part of the TCP/IP protocol suite? (Choose three.)", "o": ["ARP", "DHCP", "DNS", "FTP", "NAT", "PPP"], "a": [1, 2, 3], "e": "DNS, DHCP, and FTP are all application layer protocols in the TCP/IP protocol suite. ARP and PPP are network access layer protocols, and NAT is an internet layer protocol in the TCP/IP protocol suite."}, {"id": 156, "t": 1, "q": "Which two protocols function at the internet layer? (Choose two)", "o": ["ARP", "BOOTP", "ICMP", "IP", "PPP"], "a": [2, 3], "e": "ICMP and IP both function at the internet layer, whereas PPP is a network access layer protocol, and POP and BOOTP are application layer protocols."}, {"id": 157, "t": 0, "q": "Which publicly available resources describe protocols, processes, and technologies for the Internet but do not give implementation details?", "o": ["Request for Comments", "IRTF research papers", "protocol models", "IEEE standards"], "a": 0, "e": "✔ Request for Comments"}, {"id": 158, "t": 3, "q": "Which address on a PC does not change, even if the PC is moved to a different network?", "o": ["IP address", "default gateway address", "MAC address", "logical address"], "a": 2, "e": "✔ MAC address"}, {"id": 159, "t": 3, "q": "What is the protocol that is used to discover a physical address from a known logical address and what message type does it use?", "o": ["ARP, multicast", "DNS, unicast", "DNS, broadcast", "ARP, broadcast", "PING, multicast", "PING, broadcast"], "a": 3, "e": "An ARP request is broadcast to all devices on a LAN segment which seek the MAC address for a known IP address. Pings are used to verify connectivity between two devices, and DNS resolves URLs to IP addresses."}, {"id": 160, "t": 3, "q": "What will happen if the default gateway address is incorrectly configured on a host?", "o": ["The host cannot communicate with other hosts in the local network.", "The switch will not forward packets initiated by the host.", "The host will have to use ARP to determine the correct address of the default gateway.", "The host cannot communicate with hosts in other networks.", "A ping from the host to 127.0.0.1 would not be successful."], "a": 3, "e": "When a host needs to send a message to another host located on the same network, it can forward the message directly. However, when a host needs to send a message to a remote network, it must use the router, also known as the default gateway. This is because the data link frame address of the remote destination host cannot be used directly. Instead, the IP packet has to be sent to the router (default gateway) and the router will forward the packet toward its destination. Therefore, if the default gateway is incorrectly configured, the host can communicate with other hosts on the same network, but not with hosts on remote networks."}, {"id": 161, "t": 2, "q": "What is an important function of the physical layer of the OSI model?", "o": ["It accepts frames from the physical media.", "It encapsulates upper layer data into frames.", "It defines the media access method performed by the hardware interface.", "It encodes frames into electrical, optical, or radio wave signals."], "a": 3, "e": "The physical layer of the OSI model accepts frames from the data link layer and encodes it for transport as bits across the network media."}, {"id": 162, "t": 2, "q": "Which two statements describe the characteristics of fiber-optic cabling? (Choose two.)", "o": ["Fiber-optic cabling does not conduct electricity.", "Fiber-optic cabling has high signal loss.", "Fiber-optic cabling is primarily used as backbone cabling.", "Multimode fiber-optic cabling carries signals from multiple sending devices.", "Fiber-optic cabling uses LEDs for single-mode cab?les and laser technology for multimode cables."], "a": [0, 2], "e": "Fiber-optic cabling is primarily used for high-traffic backbone cabling and does not conduct electricity. Multimode fiber uses LEDs for signaling and single-mode fiber uses laser technology. FIber-optic cabling carries signals from only one device to another."}, {"id": 163, "t": 3, "q": "What is contained in the trailer of a data-link frame?", "o": ["logical address", "physical address", "data", "error detection"], "a": 3, "e": "The trailer in a data-link frame contains error detection information that is pertinent to the frame included in the FCS field. The header contains control information, such as the addressing, while the area that is indicated by the word “data” includes the data, transport layer PDU, and the IP header."}, {"id": 164, "t": 3, "q": "Refer to the exhibit. A ping to PC3 is issued from PC0, PC1, and PC2 in this exact order. Which MAC addresses will be contained in the S1 MAC address table that is associated with the Fa0/1 port? <i>(exhibit not shown)</i>", "o": ["just PC0 and PC1 MAC addresses", "just the PC0 MAC address", "PC0, PC1, and PC2 MAC addresses", "just the PC1 MAC address", "just the PC2 MAC address"], "a": 0, "e": "Switch S1 builds a MAC address table based on the source MAC address in the frame and the port upon which the frame enters the switch. The PC2 MAC address will be associated with port FA0/2. Because port FA0/1 of switch S1 connects with another switch, port FA0/1 will receive frames from multiple different devices. The MAC address table on switch S1 will therefore contain MAC addresses associated with each of the sending PCs."}, {"id": 165, "t": 2, "q": "How does a Layer 3 switch differ from a Layer 2 switch?", "o": ["A Layer 3 switch supports VLANs, but a Layer 2 switch does not.", "An IP address can be assigned to a physical port of a Layer 3 switch. However, this is not supported in Layer 2 switches.", "A Layer 3 switch maintains an IP address table instead of a MAC address table.", "A Layer 3 switch learns the MAC addresses that are associated with each of its ports. However, a Layer 2 switch does not."], "a": 1, "e": "✔ An IP address can be assigned to a physical port of a Layer 3 switch. However, this is not supported in Layer 2 switches."}, {"id": 166, "t": 3, "q": "What is the purpose of the routing process?", "o": ["to encapsulate data that is used to communicate across a network", "to select the paths that are used to direct traffic to destination networks", "to convert a URL name into an IP address", "to provide secure Internet file transfer", "to forward traffic on the basis of MAC addresses"], "a": 1, "e": "✔ to select the paths that are used to direct traffic to destination networks"}, {"id": 167, "t": 3, "q": "Refer to the exhibit. Consider the IP address configuration shown from PC1. What is a description of the default gateway address? <i>(exhibit not shown)</i>", "o": ["It is the IP address of the Router1 interface that connects the company to the Internet.", "It is the IP address of the Router1 interface that connects the PC1 LAN to Router1.", "It is the IP address of Switch1 that connects PC1 to other devices on the same LAN.", "It is the IP address of the ISP network device located in the cloud."], "a": 1, "e": "The default gateway is used to route packets destined for remote networks. The default gateway IP address is the address of the first Layer 3 device (the router interface) that connects to the same network."}, {"id": 168, "t": 1, "q": "Which two statements correctly describe a router memory type and its contents? (Choose two.)", "o": ["ROM is nonvolatile and contains basic diagnostic software.", "FLASH is nonvolatile and contains a limited portion of the IOS.", "ROM is nonvolatile and stores the running IOS.", "RAM is volatile and stores the IP routing table.", "NVRAM is nonvolatile and stores other system files."], "a": [0, 3], "e": "ROM is a nonvolatile memory and stores bootup instructions, basic diagnostic software, and a limited IOS. Flash is a nonvolatile memory used as permanent storage for the IOS and other system-related files. RAM is volatile memory and stores the IP routing table, IPv4 to MAC address mappings in the ARP cache, packets that are buffered or temporarily stored, the running configuration, and the currently running IOS. NVRAM is a nonvolatile memory that stores the startup configuration file."}, {"id": 169, "t": 1, "q": "In which default order will a router search for startup configuration information?", "o": ["NVRAM, RAM, TFTP", "NVRAM, TFTP, setup mode", "setup mode, NVRAM, TFTP", "TFTP, ROM, NVRAM", "flash, ROM, setup mode"], "a": 1, "e": "✔ NVRAM, TFTP, setup mode"}, {"id": 170, "t": 4, "q": "What happens when part of an Internet VoIP transmission is not delivered to the destination?", "o": ["A delivery failure message is sent to the source host.", "The part of the VoIP transmission that was lost is re-sent.", "The entire transmission is re-sent.", "The transmission continues without the missing portion."], "a": 3, "e": "✔ The transmission continues without the missing portion."}, {"id": 171, "t": 3, "q": "Which three IP addresses are private ? (Choose three.)", "o": ["10.172.168.1", "172.32.5.2", "192.167.10.10", "172.20.4.4", "192.168.5.254", "224.6.6.6"], "a": [0, 3, 4], "e": "The private IP addresses are within these three ranges: 10.0.0.0 - 10.255.255.255 172.16.0.0 - 172.31.255.255 192.168.0.0 - 192.168.255.255"}, {"id": 172, "t": 3, "q": "How many bits make up the single IPv6 hextet :10CD:?", "o": ["4", "8", "16", "32"], "a": 2, "e": "A hextet consists of 4 hexadecimal characters. Each hexadecimal character is represented by four bits, giving a total of 16 bits."}, {"id": 173, "t": 3, "q": "What is the effect of configuring the ipv6 unicast-routing command on a router?", "o": ["to assign the router to the all-nodes multicast group", "to enable the router as an IPv6 router", "to permit only unicast packets on the router", "to prevent the router from joining the all-routers multicast group"], "a": 1, "e": "When the ipv6 unicast-routing command is implemented on a router, it enables the router as an IPv6 router. Use of this command also assigns the router to the all-routers multicast group."}, {"id": 174, "t": 3, "q": "Which group of IPv6 addresses cannot be allocated as a host source address?", "o": ["FEC0::/10", "FDFF::/7", "FEBF::/10", "FF00::/8"], "a": 3, "e": "✔ FF00::/8"}, {"id": 175, "t": 3, "q": "What is the purpose of ICMP messages?", "o": ["to inform routers about network topology changes", "to ensure the delivery of an IP packet", "to provide feedback of IP packet transmissions", "to monitor the process of a domain name to IP address resolution"], "a": 2, "e": "The purpose of ICMP messages is to provide feedback about issues that are related to the processing of IP packets."}, {"id": 176, "t": 3, "q": "A network administrator needs to monitor network traffic to and from servers in a data center. Which features of an IP addressing scheme should be applied to these devices?", "o": ["random static addresses to improve security", "addresses from different subnets for redundancy", "predictable static IP addresses for easier identification", "dynamic addresses to reduce the probability of duplicate addresses"], "a": 2, "e": "When monitoring servers, a network administrator needs to be able to quickly identify them. Using a predictable static addressing scheme for these devices makes them easier to identify. Server security, redundancy, and duplication of addresses are not features of an IP addressing scheme."}, {"id": 177, "t": 3, "q": "Which two notations are useable nibble boundaries when subnetting in IPv6? (Choose two.)", "o": ["/62", "/64", "/66", "/68", "/70"], "a": [1, 3], "e": "✔ /64; /68"}, {"id": 178, "t": 4, "q": "A host PC has just booted and is attempting to lease an address through DHCP. Which two messages will the client typically broadcast on the network? (Choose two.)", "o": ["DHCPDISCOVER", "DHCPOFFER", "DHCPREQUEST", "DHCPACK", "DHCPNACK"], "a": [0, 2], "e": "When a host uses DHCP to automatically configure an IP address, the typically sends two messages: the DHCPDISCOVER message and the DHCPREQUEST message. These two messages are usually sent as broadcasts to ensure that all DHCP servers receive them. The servers respond to these messages using DHCPOFFER, DHCPACK, and DHCPNACK messages, depending on the circumstance."}, {"id": 179, "t": 4, "q": "What is the purpose of the network security accounting function?", "o": ["to require users to prove who they are", "to determine which resources a user can access", "to keep track of the actions of a user", "to provide challenge and response questions"], "a": 2, "e": "Authentication, authorization, and accounting are network services collectively known as AAA. Authentication requires users to prove who they are. Authorization determines which resources the user can access. Accounting keeps track of the actions of the user."}, {"id": 180, "t": 2, "q": "What two preconfigured settings that affect security are found on most new wireless routers? (Choose two.)", "o": ["broadcast SSID", "MAC filtering enabled", "WEP encryption enabled", "PSK authentication required", "default administrator password"], "a": [0, 4], "e": "✔ broadcast SSID; default administrator password"}, {"id": 181, "t": 4, "q": "Which type of wireless security generates dynamic encryption keys each time a client associates with an AP?", "o": ["EAP", "PSK", "WEP", "WPA"], "a": 3, "e": "✔ WPA"}, {"id": 182, "t": 2, "q": "Which two components are necessary for a wireless client to be installed on a WLAN? (Choose two.)", "o": ["media", "wireless NIC", "custom adapter", "crossover cable", "wireless bridge", "wireless client software"], "a": [1, 5], "e": "✔ wireless NIC; wireless client software"}, {"id": 183, "t": 2, "q": "When is a dial-up connection used to connect to an ISP?", "o": ["when a cellular telephone provides the service", "when a high-speed connection is provided over a cable TV network", "when a satellite dish is used", "when a regular telephone line is used"], "a": 3, "e": "✔ when a regular telephone line is used"}, {"id": 184, "t": 4, "q": "On a school network, students are surfing the web, searching the library database, and attending an audio conference with their sister school in Japan. If network traffic is prioritized with QoS, how will the traffic be classified from highest priority to lowest priority?", "o": ["audio conference, database, HTTP", "database, HTTP, audio conference", "audio conference, HTTP, database", "database, audio conference, HTTP"], "a": 0, "e": "✔ audio conference, database, HTTP"}, {"id": 185, "t": 1, "q": "During normal operation, from which location do most Cisco routers run the IOS?", "o": ["RAM", "flash", "NVRAM", "disk drive"], "a": 0, "e": "When a Cisco switch is powered on, the IOS is copied into RAM. The switch then runs the IOS from RAM, thus enhancing operating performance."}, {"id": 186, "t": 3, "q": "Which keys act as a hot key combination that is used to interrupt an IOS process?", "o": ["Ctrl-Shift-X", "Ctrl-Shift-6", "Ctrl-Z", "Ctrl-C"], "a": 1, "e": "The Cisco IOS provides both hot keys and shortcuts for configuring routers and switches. The Ctrl-Shift-6 hot key combination is used to interrupt an IOS process, such as a ping or traceroute. Ctrl-Z is used to exit the configuration mode. Ctrl-C aborts the current command. Ctrl-Shift-X has no IOS function."}, {"id": 187, "t": 4, "q": "A technician uses the ping 127.0.0.1 command. What is the technician testing?", "o": ["the TCP/IP stack on a network host", "connectivity between two adjacent Cisco devices", "connectivity between a PC and the default gateway", "connectivity between two PCs on the same network", "physical connectivity of a particular PC and the network"], "a": 0, "e": "✔ the TCP/IP stack on a network host"}, {"id": 188, "t": 2, "q": "Which device should be used for enabling a host to communicate with another host on a different network?", "o": ["switch", "hub", "router", "host"], "a": 2, "e": "✔ router"}, {"id": 189, "t": 2, "q": "Which characteristics describe fiber optic cable? (Choose two.)", "o": ["It is not affected by EMI or RFI.", "Each pair of cables is wrapped in metallic foil.", "It combines the technique of cancellation, shielding and twisting to protect data.", "It has a maximum speed of 100 Mbps.", "It is the most expensive type of LAN cabling"], "a": [0, 4], "e": "✔ It is not affected by EMI or RFI.; It is the most expensive type of LAN cabling"}, {"id": 190, "t": 2, "q": "What are two features of a physical, star network topology? (Choose two.)", "o": ["It is straightforward to troubleshoot.", "End devices are connected together by a bus.", "It is easy to add and remove end devices.", "All end devices are connected in a chain to each other.", "Each end system is connected to its respective neighbor."], "a": [0, 2], "e": "✔ It is straightforward to troubleshoot.; It is easy to add and remove end devices."}, {"id": 191, "t": 2, "q": "A frame is transmitted from one networking device to another. Why does the receiving device check the FCS field in the frame?", "o": ["to determine the physical address of the sending device", "to verify the network layer protocol information", "to compare the interface media type between the sending and receiving ends", "to check the frame for possible transmission errors", "to verify that the frame destination matches the MAC address of the receiving device"], "a": 3, "e": "✔ to check the frame for possible transmission errors"}, {"id": 192, "t": 2, "q": "What will a Layer 2 switch do when the destination MAC address of a received frame is not in the MAC table?", "o": ["It initiates an ARP request.", "It broadcasts the frame out of all ports on the switch.", "It notifies the sending host that the frame cannot be delivered.", "It forwards the frame out of all ports except for the port at which the frame was received."], "a": 3, "e": "✔ It forwards the frame out of all ports except for the port at which the frame was received."}, {"id": 193, "t": 3, "q": "Which parameter does the router use to choose the path to the destination when there are multiple routes available?", "o": ["the lower metric value that is associated with the destination network", "the lower gateway IP address to get to the destination network", "the higher metric value that is associated with the destination network", "the higher gateway IP address to get to the destination network"], "a": 0, "e": "✔ the lower metric value that is associated with the destination network"}, {"id": 194, "t": 1, "q": "Which two statements describe the functions or characteristics of ROM in a router? (Choose two.)", "o": ["stores routing tables", "allows software to be updated without replacing pluggable chips on the motherboard", "maintains instructions for POST diagnostics", "holds ARP cache", "stores bootstrap program"], "a": [2, 4], "e": "✔ maintains instructions for POST diagnostics; stores bootstrap program"}, {"id": 195, "t": 1, "q": "Which statement describes a characteristic of the Cisco router management ports?", "o": ["A console port is used for remote management of the router.", "A console port is not used for packet forwarding.", "Serial and DSL interfaces are types of management ports.", "Each Cisco router has a LED indicator to provide information about the status of the management ports."], "a": 1, "e": "✔ A console port is not used for packet forwarding."}, {"id": 196, "t": 3, "q": "What types of addresses make up the majority of addresses within the /8 block IPv4 bit space?", "o": ["private addresses", "public addresses", "multicast addresses", "experimental addresses"], "a": 1, "e": "✔ public addresses"}, {"id": 197, "t": 3, "q": "Refer to the exhibit. What is the maximum TTL value that is used to reach the destination www.cisco.com??<br>Networking Devices and Initial Configuration Course Final Exam 26 <i>(exhibit not shown)</i>", "o": ["11", "12", "13", "14"], "a": 2, "e": "Traceroute (in this case the command tracert) sets the TTL field to a value of 1 and sends the packet. At each router hop, this value is decreased by one and a \"TTL expired\" message is sent back to the source host. This message has a source address which is used by the host to build the trace. The host then progressively increments the TTL field (2, 3, 4...) for each sequence of messages until the destination is reached or it is incremented to a predefined maximum. Because the executed command reached the destination in the 13th line, the TTL was increased up to the value of 13."}, {"id": 198, "t": 3, "q": "A company has a network address of 192.168.1.64 with a subnet mask of 255.255.255.192. The company wants to create two subnetworks that would contain 10 hosts and 18 hosts respectively. Which two networks would achieve that? (Choose two.)", "o": ["192.168.1.16/28", "192.168.1.64/27", "192.168.1.128/27", "192.168.1.96/28", "192.168.1.192/28"], "a": [1, 3], "e": "Subnet 192.168.1.64 /27 has 5 bits that are allocated for host addresses and therefore will be able to support 32 addresses, but only 30 valid host IP addresses. Subnet 192.168.1.96/28 has 4 bits for host addresses and will be able to support 16 addresses, but only 14 valid host IP addresses"}, {"id": 199, "t": 3, "q": "In a network that uses IPv4, what prefix would best fit a subnet containing 100 hosts?", "o": ["/23", "/24", "/25", "/26"], "a": 2, "e": "✔ /25"}, {"id": 200, "t": 0, "q": "Which protocol supports rapid delivery of streaming media?", "o": ["Transmission Control Protocol", "Real-Time Transport Protocol", "Secure File Transfer Protocol", "Video over Internet Protocol"], "a": 1, "e": "✔ Real-Time Transport Protocol"}, {"id": 201, "t": 4, "q": "Why would a network administrator use the tracert utility?", "o": ["to determine the active TCP connections on a PC", "to check information about a DNS name in the DNS server", "to identify where a packet was lost or delayed on a network", "to display the IP address, default gateway, and DNS server address for a PC"], "a": 2, "e": "The tracert utility is used to identify the path a packet takes from source to destination. Tracert is commonly used when packets are dropped or not reaching a specific destination."}, {"id": 202, "t": 4, "q": "Which WLAN security protocol generates a new dynamic key each time a client establishes a connection with the AP?", "o": ["EAP", "PSK", "WEP", "WPA"], "a": 3, "e": "✔ WPA"}, {"id": 203, "t": 1, "q": "Three office workers are using the corporate network. The first employee uses a web browser to view a company web page in order to read some announcements. The second employee accesses the corporate database to perform some financial transactions. The third employee participates in an important live audio conference with other office workers in branch offices. If QoS is implemented on this network, what will be the priorities from highest to lowest of the different data types?", "o": ["audio conference, financial transactions, web page", "financial transactions, web page, audio conference", "audio conference, web page, financial transactions", "financial transactions, audio conference, web page"], "a": 0, "e": " QoS mechanisms enable the establishment of queue management strategies that enforce priorities for different categories of application data. Thus, this queuing enables voice data to have priority over transaction data, which has priority over web data."}, {"id": 204, "t": 1, "q": "A network administrator is making changes to the configuration of a router. After making the changes and verifying the results, the administrator issues the copy running-config startup-config command. What will happen after this command executes?", "o": ["The configuration will be copied to flash.", "The configuration will load when the router is restarted.", "The new configuration file will replace the IOS file.", "The changes will be lost when the router restarts."], "a": 1, "e": "✔ The configuration will load when the router is restarted."}, {"id": 205, "t": 4, "q": "What information does the loopback test provide?", "o": ["The TCP/IP stack on the device is working correctly.", "The device has end-to-end connectivity.", "DHCP is working correctly.", "The Ethernet cable is working correctly.", "The device has the correct IP address on the network."], "a": 0, "e": "Because the loopback test sends packets back to the host device, it does not provide information about network connectivity to other hosts. The loopback test verifies that the host NIC, drivers, and TCP/IP stack are functioning."}, {"id": 206, "t": 2, "q": "What happens when a switch receives a frame and the calculated CRC value is different than the value that is in the FCS field?", "o": ["The switch places the new CRC value in the FCS field and forwards the frame.", "The switch notifies the source of the bad frame.", "The switch drops the frame.", "The switch floods the frame to all ports except the port through which the frame arrived to notify the hosts of the error."], "a": 2, "e": "The purpose of the CRC value in the FCS field is to determine if the frame has errors. If the frame does have errors, then the frame is dropped by the switch."}, {"id": 207, "t": 2, "q": "What is the auto-MDIX feature on a switch?", "o": ["the automatic configuration of an interface for 10/100/1000 Mb/s operation", "the automatic configuration of an interface for a straight-through or a crossover Ethernet cable connection", "the automatic configuration of full-duplex operation over a single Ethernet copper or optical cable", "the ability to turn a switch interface on or off accordingly if an active connection is detected"], "a": 1, "e": "The auto-MDIX enables a switch to use a crossover or a straight-through Ethernet cable to connect to a device regardless of the device on the other end of the connection."}, {"id": 208, "t": 2, "q": "What are the two main components of Cisco Express Forwarding (CEF)? (Choose two.)", "o": ["adjacency tables", "MAC-address tables", "routing tables", "ARP tables", "forwarding information base (FIB)"], "a": [0, 4], "e": "The forwarding information base (FIB) and adjacency tables are the main components of CEF. The FIB is similar to a routing table, but neither the routing table, nor the ARP table, nor the MAC-address table is part of CEF."}, {"id": 209, "t": 3, "q": "Which statement describes the sequence of processes executed by a router when it receives a packet from a host to be delivered to a host on another network?", "o": ["It receives the packet and forwards it directly to the destination host.", "It de-encapsulates the packet, selects the appropriate path, and encapsulates the packet to forward it toward the destination host", "It de-encapsulates the packet and forwards it toward the destination host.", "It selects the path and forwards it toward the destination host."], "a": 1, "e": "The router receives the packet, de-encapsulates it to select the appropriate path, encapsulates the packet, and then forwards it toward the destination host."}, {"id": 210, "t": 3, "q": "Refer to the exhibit. Router R1 has two interfaces that were configured with correct IP addresses and subnet masks. Why does the show ip route command output not display any information about the directly connected networks? <i>(exhibit not shown)</i>", "o": ["The directly connected networks have to be created manually to be displayed in the routing table.", "The routing table will only display information about these networks when the router receives a packet.", "The no shutdown command was not issued on these interfaces.", "The gateway of last resort was not configured."], "a": 2, "e": "✔ The no shutdown command was not issued on these interfaces."}, {"id": 211, "t": 4, "q": "Which three statements characterize the transport layer protocols? (Choose three.)", "o": ["TCP and UDP port numbers are used by application layer protocols.", "TCP uses port numbers to provide reliable transportation of IP packets.", "UDP uses windowing and acknowledgments for reliable transfer of data.", "TCP uses windowing and sequencing to provide reliable transfer of data.", "TCP is a connection-oriented protocol. UDP is a connectionless protocol."], "a": [0, 3, 4], "e": "✔ TCP and UDP port numbers are used by application layer protocols.; TCP uses windowing and sequencing to provide reliable transfer of data.; TCP is a connection-oriented protocol. UDP is a connectionless protocol."}, {"id": 212, "t": 4, "q": "Which statement is true regarding the UDP client process during a session with a server?", "o": ["Datagrams that arrive in a different order than that in which they were sent are not placed in order.", "A session must be established before datagrams can be exchanged.", "A three-way handshake takes place before the transmission of data begins.", "Application servers have to use port numbers above 1024 in order to be UDP capable."], "a": 0, "e": "Because there are no sequence numbers in UDP segments, there is no possibility to arrange the datagrams in the correct order. Sessions and three-way handshake are related to TCP communications. UDP servers can use registered or nonregistered port numbers to listen to clients."}, {"id": 213, "t": 3, "q": "Which two components are configured via software in order for a PC to participate in a network environment? (Choose two.)", "o": ["MAC address", "IP address", "kernel", "shell", "subnet mask"], "a": [1, 4], "e": "✔ IP address; subnet mask"}, {"id": 214, "t": 3, "q": "Which two reasons generally make DHCP the preferred method of assigning IP addresses to hosts on large networks? (Choose two.)", "o": ["It eliminates most address configuration errors.", "It ensures that addresses are only applied to devices that require a permanent address.", "It guarantees that every device that needs an address will get one.", "It provides an address only to devices that are authorized to be connected to the network.", "It reduces the burden on network support staff."], "a": [0, 4], "e": "DHCP is generally the preferred method of assigning IP addresses to hosts on large networks because it reduces the burden on network support staff and virtually eliminates entry errors. However, DHCP itself does not discriminate between authorized and unauthorized devices and will assign configuration parameters to all requesting devices. DHCP servers are usually configured to assign addresses from a subnet range, so there is no guarantee that every device that needs an address will get one."}, {"id": 215, "t": 3, "q": "What is the subnet address for the address 2001:DB8:BC15:A:12AB::1/64?", "o": ["2001:DB8:BC15::0", "2001:DB8:BC15:A::0", "2001:DB8:BC15:A:1::1", "2001:DB8:BC15:A:12::0"], "a": 1, "e": "✔ 2001:DB8:BC15:A::0"}, {"id": 216, "t": 3, "q": "Which field in an IPv4 packet header will typically stay the same during its transmission?", "o": ["Packet Length", "Destination Address", "Flag", "Time-to-Live"], "a": 1, "e": "The value in the Destination Address field in an IPv4 header will stay the same during its transmission. The other options might change during its transmission."}, {"id": 217, "t": 3, "q": "What must be configured to enable Cisco Express Forwarding (CEF) on most Cisco devices that perform Layer 3 switching?", "o": ["Manually configure next-hop Layer 2 addresses.", "Issue the no shutdown command on routed ports.", "CEF is enabled by default, so no configuration is necessary.", "Manually map Layer 2 addresses to Layer 3 addresses to populate the forwarding information base (FIB)."], "a": 2, "e": "✔ CEF is enabled by default, so no configuration is necessary."}, {"id": 218, "t": 3, "q": "What is the purpose of adjacency tables as used in Cisco Express Forwarding (CEF)?", "o": ["to populate the forwarding information base (FIB)", "to maintain Layer 2 next-hop addresses", "to allow the separation of Layer 2 and Layer 3 decision making", "to update the forwarding information base (FIB)"], "a": 1, "e": "✔ to maintain Layer 2 next-hop addresses"}, {"id": 219, "t": 3, "q": "Which statement describes a characteristic of the network layer in the OSI model?", "o": ["It manages the data transport between the processes running on each host.", "In the encapsulation process, it adds source and destination port numbers to the IP header.", "When a packet arrives at the destination host, its IP header is checked by the network layer to determine where the packet has to be routed.", "Its protocols specify the packet structure and processing used to carry the data from one host to another."], "a": 3, "e": "The transport layer manages the data transport between the processes that are running on each host. In the encapsulation process, the network layer adds the IP header information, such as the IP address of the source (sending) and destination (receiving) hosts. When a packet arrives at the network layer of the destination host, the host checks the IP header of the packet to verify if the destination IP address within the header matches its own IP address."}, {"id": 220, "t": 3, "q": "A user gets an IP address of 192.168.0.1 from the company network administrator. A friend of the user at a different company gets the same IP address on another PC. How can two PCs use the same IP address and still reach the Internet, send and receive email, and search the web?", "o": ["Both users must be using the same Internet Service Provider.", "ISPs use Network Address Translation to change a user IP address into an address that can be used on the Internet.", "ISPs use Domain Name Service to change a user IP address into a public IP address that can be used on the Internet.", "Both users must be on the same network."], "a": 1, "e": "As user traffic from behind an ISP firewall reaches the gateway device, Network Address Translation changes private IP addresses into a public, routable IP address. Private user addresses remain hidden from the public Internet, and thus more than one user can have the same private IP address, regardless of ISP."}, {"id": 221, "t": 4, "q": "Why does HTTP use TCP as the transport layer protocol?", "o": ["to ensure the fastest possible download speed", "because HTTP is a best-effort protocol", "because transmission errors can be tolerated easily", "because HTTP requires reliable delivery"], "a": 3, "e": "When a host requests a web page, transmission reliability and completeness must be guaranteed. Therefore, HTTP uses TCP as its transport layer protocol."}, {"id": 222, "t": 3, "q": "What is the valid most compressed format possible of the IPv6 address 2001:0DB8:0000:AB00:0000:0000:0000:1234?", "o": ["2001:DB8:0:AB00::1234", "2001:DB8:0:AB::1234", "2001:DB8::AB00::1234", "2001:DB8:0:AB:0:1234"], "a": 0, "e": "There are two rules defining how an IPv6 address can be compressed. The first rule states that leading zeros in a hextet can be eliminated. The second rule states that a single :: can be used to represent one or more contiguous all zero hextets. There can be one and only one :: in an IPv6 address."}, {"id": 223, "t": 0, "q": "What field content is used by ICMPv6 to determine that a packet has expired?", "o": ["TTL field", "CRC field", "Hop Limit field", "Time Exceeded field"], "a": 2, "e": "ICMPv6 sends a Time Exceeded message if the router cannot forward an IPv6 packet because the packet expired. The router uses a hop limit field to determine if the packet has expired, and does not have a TTL field."}, {"id": 224, "t": 4, "q": "Which firewall technique blocks incoming packets unless they are responses to internal requests?", "o": ["port filtering", "stateful packet inspection", "URL filtering", "application filtering"], "a": 1, "e": "✔ stateful packet inspection"}, {"id": 225, "t": 1, "q": "A network technician is investigating network connectivity from a PC to a remote host with the address 10.1.1.5. Which command issued on the PC will return to the technician the complete path to the remote host?", "o": ["trace 10.1.1.5", "traceroute 10.1.1.5", "tracert 10.1.1.5", "ping 10.1.1.5"], "a": 2, "e": "✔ tracert 10.1.1.5"}, {"id": 226, "t": 2, "q": "What is a possible hazard that can be caused by network cables in a fire?", "o": ["The cable insulation could be flammable.", "Users could be exposed to excessive voltage.", "Network cables could be exposed to water.", "The network cable could explode."], "a": 0, "e": "✔ The cable insulation could be flammable."}, {"id": 227, "t": 2, "q": "What device is commonly used to verify a UTP cable?", "o": ["a multimeter", "an Optical Time Domain Reflectometer", "a cable tester", "an ohmmeter"], "a": 2, "e": "✔ a cable tester"}, {"id": 228, "t": 2, "q": "What needs to be checked when testing a UTP network cable?", "o": ["capacitance", "wire map", "inductance", "flexibility"], "a": 1, "e": "✔ wire map"}, {"id": 229, "t": 3, "q": "Which function is provided by TCP?", "o": ["data encapsulation", "detection of missing packets", "communication session control", "path determination for data packets"], "a": 1, "e": "✔ detection of missing packets"}, {"id": 230, "t": 3, "q": "What does a router use to determine where to send data it receives from the network?", "o": ["an ARP table", "a routing table", "the destination PC physical address", "a switching table"], "a": 1, "e": "✔ a routing table"}, {"id": 231, "t": 1, "q": "Which router interface should be used for direct remote access to the router via a modem?", "o": ["an inband router interface", "a console port", "a serial WAN interface", "an AUX port"], "a": 3, "e": "✔ an AUX port"}, {"id": 232, "t": 1, "q": "A technician is configuring a router to allow for all forms of management access. As part of each different type of access, the technician is trying to type the command login. Which configuration mode should be entered to do this task?", "o": ["user executive mode", "global configuration mode", "any line configuration mode", "privileged EXEC mode"], "a": 2, "e": "The command login is used to allow access to a router or switch through aux lines, console lines, and Telnet lines."}, {"id": 233, "t": 3, "q": "Which statement is true about an interface that is configured with the IPv6 address command?", "o": ["IPv6 traffic-forwarding is enabled on the interface.", "A link-local IPv6 address is automatically configured on the interface.", "A global unicast IPv6 address is dynamically configured on the interface.", "Any IPv4 addresses that are assigned to the interface are replaced with an IPv6 address."], "a": 1, "e": "✔ A link-local IPv6 address is automatically configured on the interface."}, {"id": 234, "t": 3, "q": "Refer to the exhibit. An administrator must send a message to everyone on the router A network. What is the broadcast address for network 172.16.16.0/22? <i>(exhibit not shown)</i>", "o": ["172.16.16.255", "172.16.20.255", "172.16.19.255", "172.16.23.255", "172.16.255.255"], "a": 2, "e": "The 172.16.16.0/22 network has 22 bits in the network portion and 10 bits in the host portion. Converting the network address to binary yields a subnet mask of 255.255.252.0. The range of addresses in this network will end with the last address available before 172.16.20.0. Valid host addresses for this network range from 172.16.16.1-172.16.19.254, making 172.16.19.255 the broadcast address."}, {"id": 235, "t": 3, "q": "How many additional bits should be borrowed from a /26 subnet mask in order to create subnets for WAN links that need only 2 useable addresses?", "o": ["2", "3", "4", "5", "6"], "a": 2, "e": "WAN links needing only 2 useable addresses use a /30 subnet, so 4 additional bits would need to be borrowed."}, {"id": 236, "t": 1, "q": "Refer to the exhibit. The administrator configured the access to the console and the vty lines of a router. Which conclusion can be drawn from this configuration? <i>(exhibit not shown)</i>", "o": ["Unauthorized individuals can connect to the router via Telnet without entering a password.", "Because the IOS includes the login command on the vty lines by default, access to the device via Telnet will require authentication.", "Access to the vty lines will not be allowed via Telnet by anyone.", "Because the login command was omitted, the password cisco command is not applied to the vty lines."], "a": 1, "e": "By default, the IOS includes the login command on the vty lines. This prevents Telnet access to the device without authentication. If, by mistake, the no login command is set, which removes the requirement for authentication, unauthorized persons could connect across the network to the line through Telnet. This would be a major security risk."}, {"id": 237, "t": 1, "q": "An administrator issued the service password-encryption command to apply encryption to the passwords configured for enable password, vty, and console lines. What will be the consequences if the administrator later issues the no service password-encryption command?", "o": ["It will remove encryption from all passwords.", "It will reverse only the vty and console password encryptions.", "It will not reverse any encryption.", "It will reverse only the enable password encryption."], "a": 2, "e": "The service password-encryption command can be executed and the encryption will be applied to the passwords. Once the encryption has been applied, issuing the no service-password encryption command does not reverse the encryption."}, {"id": 238, "t": 3, "q": "What are two features of ARP? (Choose two.)", "o": ["If a host is ready to send a packet to a local destination device and it has the IP address but not the MAC address of the destination, it generates an ARP broadcast.", "An ARP request is sent to all devices on the Ethernet LAN and contains the IP address of the destination host and its multicast MAC address.", "When a host is encapsulating a packet into a frame, it refers to the MAC address table to determine the mapping of IP addresses to MAC addresses.", "If no device responds to the ARP request, then the originating node will broadcast the data packet to all devices on the network segment.", "If a device receiving an ARP request has the destination IPv4 address, it responds with an ARP reply."], "a": [0, 4], "e": "When a node encapsulates a data packet into a frame, it needs the destination MAC address. First it determines if the destination device is on the local network or on a remote network. Then it checks the ARP table (not the MAC table) to see if a pair of IP address and MAC address exists for either the destination IP address (if the destination host is on the local network) or the default gateway IP address (if the destination host is on a remote network). If the match does not exist, it generates an ARP broadcast to seek the IP address to MAC address resolution. Because the destination MAC address is unknown, the ARP request is broadcast with the MAC address FFFF.FFFF.FFFF. Either the destin"}, {"id": 239, "t": 4, "q": "A network administrator is enabling services on a newly installed server. Which two statements describe how services are used on a server? (Choose two.)", "o": ["Data sent with a service that uses TCP is received in the order the data was sent.", "A port is considered to be open when it has an active server application that is assigned to it.", "An individual server can have two services that are assigned to the same port number.", "An individual server cannot have multiple services running at the same time.", "Server security can be improved by closing ports that are associated with unused services."], "a": [1, 4], "e": "✔ A port is considered to be open when it has an active server application that is assigned to it.; Server security can be improved by closing ports that are associated with unused services."}, {"id": 240, "t": 3, "q": "Given the binary address of 11101100 00010001 00001100 00001010, which address does this represent in dotted decimal format?", "o": ["234.17.10.9", "234.16.12.10", "236.17.12.6", "236.17.12.10"], "a": 3, "e": "The binary number 11101100 00010001 00001100 00001010 translates to 236.17.12.10."}, {"id": 241, "t": 4, "q": "A particular telnet site does not appear to be responding on a Windows 7 computer. What command could the technician use to show any cached DNS entries for this web page?", "o": ["ipconfig /all", "arp -a", "ipconfig /displaydns", "nslookup"], "a": 2, "e": "✔ ipconfig /displaydns"}, {"id": 242, "t": 4, "q": "Which statement is true about DHCP operation?", "o": ["When a device that is configured to use DHCP boots, the client broadcasts a DHCPDISCOVER message to identify any available DHCP servers on the network.", "A client must wait for lease expiration before it sends another DHCPREOUEST message.", "The DHCPDISCOVER message contains the IP address and sub net masK to be assigned, the IP address of the DNS server, and the IP address of the default gateway.", "If the client receives several DHCPOFFER messages from different servers, it sends a unicast DHCPREOUEST message to the server from which it chooses to obtain the IP information."], "a": 0, "e": "The client broadcasts a DHCPDISCOVER message to identify any available DHCP servers on the network. A DHCP server replies with a DHCPOFFER message. This message offers to the client a lease that contains such information as the IP address and subnet mask to be assigned, the IP address of the DNS server, and the IP address of the default gateway. After the client receives the lease, the received information must be renewed through another DHCPREQUEST message prior to the lease expiration."}, {"id": 243, "t": 4, "q": "Which type of wireless security is easily compromised?", "o": ["EAP", "PSK", "WEP", "WPA"], "a": 2, "e": "✔ WEP"}, {"id": 244, "t": 0, "q": "A network administrator notices that the throughput on the network appears lower than expected when compared to the end-to-end network bandwidth. Which three factors can explain this difference? (Choose three.)", "o": ["the amount of traffic", "the type of data encapsulation in use", "the type of traffic", "the number and type of network devices that the data is crossing", "the bandwidth of the connection to the ISP", "the reliability of the network backbone"], "a": [0, 2, 3], "e": "✔ the amount of traffic; the type of traffic; the number and type of network devices that the data is crossing"}, {"id": 245, "t": 4, "q": "A host PC is attempting to lease an address through DHCP. What message is sent by the server to the client know it is able to use the provided IP information?", "o": ["DHCPDISCOVER", "DHCPOFFER", "DHCPPREQUEST", "DHCPACK", "DHCPNACK"], "a": 3, "e": "✔ DHCPACK"}, {"id": 246, "t": 1, "q": "A network administrator is configuring access control to switch SW1. If the administrator uses console line to connect to the switch, which password is needed to access user EXEC mode?", "o": ["letmein", "secretin", "lineconin", "linevtyin"], "a": 2, "e": " Telnet accesses a network device through the virtual interface configured with the line VTY command. The password configured under this is required to access the user EXEC mode. The password configured under the line console 0 command is required to gain entry through the console port, and the enable and enable secret passwords are used to allow entry into the privileged EXEC mode."}, {"id": 247, "t": 3, "q": "How many bits would need to be borrowed if a network admin were given the IP addressing scheme of 172.16.0.0/16 and needed no more than 16 subnet with equal number of hosts?", "o": ["10", "12", "2", "4", "8"], "a": 3, "e": "✔ 4"}, {"id": 248, "t": 4, "q": "Which statement best describes the operation of the File Transfer Protocol?", "o": ["An FTP client uses a source port number of 21 and a randomly generated destination port number during the establishment of control traffic with an FTP Server.", "An FTP client uses a source port number of 20 and a randomly generated destination port number during the establishment of data traffic with an FTP Server.", "An FTP server uses a source port number of 20 and a randomly generated destination port number during the establishment of control traffic with an FTP client.", "An FTP server uses a source port number of 21 and a randomly generated destination port number during the establishment of control traffic with an FTP client."], "a": 3, "e": " When using the File Transfer Protocol, an FTP client uses a randomly generated source port number, but targets a destination port number of 20 or 21 on the FTP server. The destination port numbers depend on whether it is the first connection for control traffic on port 21 or the second connection for data traffic on port 20."}, {"id": 249, "t": 1, "q": "A client is establishing a TCP session with a server. How is the acknowledgment number in the response segment to the client determined?", "o": ["The acknowledgment number field is modified by adding 1 to the randomly chosen initial sequence number in response to the client.", "The acknowledgment number is set to 11 to signify an acknowledgment packet and synchronization packet back to the client.", "The acknowledgment number field uses a random source port number in response to the client.", "The acknowledgment number is set to 1 to signify an acknowledgment packet back to the client."], "a": 0, "e": " To establish a session with the client, the TCP server will acknowledge the receipt of the SYN segment from the client. The server sends a segment back to the client with the ACK flag set indicating that the acknowledgment number is significant.The value of the acknowledgment number field is equal to the randomly chosen initial sequence number (ISN) plus 1."}, {"id": 250, "t": 2, "q": "What type of communication rule would best describe CSMA/CD?", "o": ["message encapsulation", "flow control", "message encoding", "access method"], "a": 3, "e": " Carrier sense multiple access collision detection (CSMA/CD) is the access method used with Ethernet. The access method rule of communication dictates how a network device is able to place a signal on the carrier. CSMA/CD dictates those rules on an Ethernet network and CSMA/CA dictates those rules on an 802.11 wireless LAN."}, {"id": 251, "t": 3, "q": "What is the primary reason to subnet IPv6 prefixes?", "o": ["to conserve IPv6 addresses", "to avoid wasting IPv6 addresses", "to conserve IPv6 prefixes", "to create a hierarchical Layer 3 network design"], "a": 3, "e": "✔ to create a hierarchical Layer 3 network design"}, {"id": 252, "t": 0, "q": "Which statement describes data throughput?", "o": ["It is the measure of the bits transferred across the media under perfect conditions.", "It is the measure of the bits transferred across the media over a given period of time.", "It indicates the capacity of a particular medium to carry data.", "It is the guaranteed data transfer rate offered by an ISP."], "a": 1, "e": "✔ It is the measure of the bits transferred across the media over a given period of time."}, {"id": 253, "t": 3, "q": "What are three important considerations when planning the structure of an IP addressing scheme? (Choose three.)", "o": ["preventing duplication of addresses", "providing and controlling access", "documenting the network", "monitoring security and performance", "conserving addresses", "implementing new services"], "a": [0, 1, 3], "e": "✔ preventing duplication of addresses; providing and controlling access; monitoring security and performance"}, {"id": 254, "t": 3, "q": "What is the metric value that is used to reach the 10.1.1.0 network in the following routing table entry? D 10.1.1.0/24 [90/2170112] via 209.165.200.226, 00:00:05, Serial0/0/0", "o": ["24", "90", "05", "2170112"], "a": 3, "e": "✔ 2170112"}, {"id": 255, "t": 4, "q": "Which two services or protocols use the preferred UDP protocol for fast transmission and low overhead? (Choose two)", "o": ["VoIP", "DNS", "HTTP", "FTP", "POP3"], "a": [0, 1], "e": " Both DNS and VoIP use UDP to provide low overhead services within a network implementation."}, {"id": 256, "t": 4, "q": "What action does a DHCPv4 client take if it receives more than one DHCPOFFER from multiple DHCP servers?", "o": ["It sends a DHCPREQUEST that identifies which lease offer the client is accepting.", "It sends a DHCPNAK and begins the DHCP process over again.", "It discards both offers and sends a new DHCPDISCOVER.", "It accepts both DHCPOFFER messages and sends a DHCPACK."], "a": 0, "e": "If there are multiple DHCP servers in a network, it is possible for a client to receive more than one DHCPOFFER. In this scenario, the client will only send one DHCPREQUEST, which includes the server from which the client is accepting the offer."}, {"id": 257, "t": 3, "q": "To what legacy address class does the address 10.0.0.0 belong?", "o": ["Class B", "Class D", "Class A", "Class C", "Class E"], "a": 2, "e": "✔ Class A"}, {"id": 258, "t": 3, "q": "How many IPv4 addresses are available to be assigned to hosts on a network that has a mask of 255.255.255.248?", "o": ["16", "14", "8", "254", "6", "2"], "a": 4, "e": "✔ 6"}, {"id": 259, "t": 2, "q": "What type of communication medium is used with a wireless LAN connection?", "o": ["radio waves", "fiber", "microwave", "UTP"], "a": 0, "e": " A wired LAN connection commonly uses UTP. A wireless LAN connection uses radio waves."}, {"id": 260, "t": 3, "q": "Which method of IPv6 prefix assignment relies on the prefix contained in RA messages?", "o": ["EUI-64", "static", "SLAAC", "stateful DHCPv6"], "a": 2, "e": " Stateless Address Autoconfiguration (SLAAC) relies on information received in router advertisement (RA) messages in order to automatically create an IPv6 address. The RA messages contain information such as the network prefix and prefix length, which the host combines with an interface ID in order to make a unique IPv6 unicast address."}, {"id": 261, "t": 4, "q": "What is a characteristic of DNS?", "o": ["DNS servers can cache recent queries to reduce DNS query traffic.", "DNS servers are programmed to drop requests for name translations that are not within their zone.", "All DNS servers must maintain mappings for the entire DNS structure.", "DNS relies on a hub-and-spoke topology with centralized servers."], "a": 0, "e": " DNS uses a hierarchy for decentralized servers to perform name resolution. DNS servers only maintain records for their zone and can cache recent queries so that future queries do not produce excessive DNS traffic."}, {"id": 262, "t": 3, "q": "What information is maintained in the CEF adjacency table?", "o": ["Layer 2 next hops", "MAC address to IPv4 address mappings", "IP address to interface mappings", "the IP addresses of all neighboring routers"], "a": 0, "e": "✔ Layer 2 next hops"}, {"id": 263, "t": 4, "q": "What is an example of a top-level domain?", "o": ["root.cisco.com", "http://www.cisco.com", ".com", "cisco.com"], "a": 2, "e": " Top-level domains represent a country or type of organization, such as .com or .edu."}, {"id": 264, "t": 4, "q": "Which protocol requires the establishment of a session between sender and receiver hosts prior to transmitting data?", "o": ["UDP", "TCP", "IP", "ICMP"], "a": 1, "e": "✔ TCP"}, {"id": 265, "t": 4, "q": "Which two protocols operate at the top layer of the TCP/IP protocol suite? (Choose two.)", "o": ["TCP", "IP", "UDP", "POP", "DNS", "Ethernet"], "a": [3, 4], "e": "The top layer of the TCP/IP protocol suite is the application layer, which provides the primary interface for network-aware software to interact with the underlying network infrastructure. Within this model, both DNS (Domain Name System) and POP (Post Office Protocol) function at this highest level to facilitate specific user-facing services, such as translating human-readable domain names into numeric IP addresses and enabling the retrieval of email from mail servers. While other protocols like TCP and UDP operate at the transport layer to manage end-to-end communication, and IP operates at the internet layer to handle routing, DNS and POP are responsible for defining the content and format"}, {"id": 266, "t": 3, "q": "What is a characteristic of multicast messages?", "o": ["They are sent to all hosts on a network.", "They must be acknowledged.", "They are sent to a select group of hosts.", "They are sent to a single destination."], "a": 2, "e": "✔ They are sent to a select group of hosts."}, {"id": 267, "t": 1, "q": "In what networking model would eDonkey, eMule, BitTorrent, Bitcoin, and LionShare be used?", "o": ["master-slave", "client-based", "peer-to-peer", "point-to-point"], "a": 2, "e": "In a peer-to-peer networking model, data is exchanged between two network devices without the use of a dedicated server. Peer-to-peer applications such as Shareaz, eDonkey, and Bitcoin allow one network device to assume the role of server, while one or more other network devices assume the role of client using the peer-to-peer application."}, {"id": 268, "t": 1, "q": "A network technician is attempting to configure an interface by entering the following command: SanJose(config)# ip address 192.168.2.1 255.255.255.0 . The command is rejected by the device. What is the reason for this?", "o": ["The interface is shutdown and must be enabled before the switch will accept the IP address.", "The subnet mask information is incorrect.", "The command syntax is wrong.", "The command is being entered from the wrong mode of operation."], "a": 3, "e": "The wrong mode of operation is being used. The CLI prompt indicates that the mode of operation is global configuration. IP addresses must be configured from interface configuration mode, as indicated by the SanJose(config-if)# prompt."}, {"id": 269, "t": 3, "q": "Refer to the exhibit. A company uses the address block of 128.107.0.0/16 for its network. What subnet mask would provide the maximum number of equal size subnets while providing enough host addresses for each subnet in the exhibit? <i>(exhibit not shown)</i>", "o": ["255.255.255.192", "255.255.255.0", "255.255.255.128", "255.255.255.240", "255.255.255.224"], "a": 2, "e": "The largest subnet in the topology has 100 hosts in it so the subnet mask must have at least 7 host bits in it (27-2=126). 255.255.255.0 has 8 hosts bits, but this does not meet the requirement of providing the maximum number of subnets."}];